window.CERT_DATA=window.CERT_DATA||{};window.CERT_DATA['bigdata-9']={"round":9,"cert":"bigdata","questions":[{"id":"6a6a00621bbde79cd2c72bcb","number":1,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>다음 중 개인정보보호 목적으로 활용되는 익명처리 기법에 해당하지 않는 것은?</p>","choices":[{"n":1,"html":"특이화"},{"n":2,"html":"가명처리"},{"n":3,"html":"데이터 범주화"},{"n":4,"html":"데이터 섭동"}],"answer":[1],"explain":{"mine":"<p>가명처리, 데이터 범주화, 데이터 섭동(값에 잡음을 더해 변형)은 모두 익명처리(비식별화) 기법입니다. <b>'특이화'라는 기법은 존재하지 않으며</b>, 오히려 특정 개인이 두드러지게 만든다는 어감으로 비식별화와 반대 방향입니다(1번).</p>"}},{"id":"6a6a00621bbde79cd2c72bce","number":2,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>데이터 품질의 진단과 개선을 수행하는 6단계 절차로 올바른 것은?</p>","choices":[{"n":1,"html":"진단대상 정의 → 품질진단 실시 → 진단결과 분석 → 개선계획 수립 → 품질통제 → 개선 수행"},{"n":2,"html":"진단대상 정의 → 품질진단 실시 → 진단결과 분석 → 개선계획 수립 → 개선 수행 → 품질통제"},{"n":3,"html":"진단대상 정의 → 품질진단 실시 → 진단결과 분석 → 품질통제 → 개선계획 수립 → 개선 수행"},{"n":4,"html":"진단대상 정의 → 품질진단 실시 → 개선계획 수립 → 진단결과 분석 → 품질통제 → 개선 수행"}],"answer":[2],"explain":{"mine":"<p>데이터 품질 진단·개선 절차는 <b>진단대상 정의 → 품질진단 실시 → 진단결과 분석 → 개선계획 수립 → 개선 수행 → 품질통제</b> 순입니다(2번). 개선을 실제로 수행한 뒤에 그 상태가 유지되도록 통제하는 것이 마지막 단계입니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bc3","number":3,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>빅데이터 분석을 데이터 분석 시스템 구현과 함께 수행할 때, 그 진행 절차로 올바른 것은?</p>","choices":[{"n":1,"html":"분석 기획 → 데이터 준비 → 데이터 분석 → 평가 및 전개 → 시스템 구현"},{"n":2,"html":"분석 기획 → 데이터 준비 → 시스템 구현 → 데이터 분석 → 평가 및 전개"},{"n":3,"html":"분석 기획 → 데이터 준비 → 데이터 분석 → 시스템 구현 → 평가 및 전개"},{"n":4,"html":"분석 기획 → 시스템 구현 → 데이터 준비 → 데이터 분석 → 평가 및 전개"}],"answer":[3],"explain":{"mine":"<p>시스템 구현을 포함한 빅데이터 분석 절차는 <b>분석 기획 → 데이터 준비 → 데이터 분석 → 시스템 구현 → 평가 및 전개</b>입니다(3번). 분석으로 검증된 모델을 시스템으로 구현한 뒤, 전체 결과를 평가하고 운영 환경에 전개합니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bca","number":4,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>데이터셋에서 발견되는 잡음(Noise) 데이터를 처리하는 기법으로 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"구간화(Binning)"},{"n":2,"html":"회귀값으로 대치(Regression)"},{"n":3,"html":"군집화(Clustering)"},{"n":4,"html":"표준화(Standardization)"}],"answer":[4],"explain":{"mine":"<p>잡음 처리(평활화)에는 구간화(Binning), 회귀 적합, 군집화(이상 패턴 식별)가 활용됩니다. <b>표준화는 평균 0·분산 1로 스케일을 바꾸는 변환</b>일 뿐 잡음을 제거하지 못하므로 4번이 답입니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bcc","number":5,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>환자 진료 기록처럼 민감한 데이터를 다룰 때, 노이즈를 추가하는 방식으로 데이터를 비식별화한 뒤 분석 작업을 진행한다. 이러한 기법을 가리키는 용어는 무엇인가?</p>","choices":[{"n":1,"html":"L-다양성(L-Diversity)"},{"n":2,"html":"데이터 가명 처리(Pseudonymization)"},{"n":3,"html":"데이터 차등 정보보호(Differential Privacy)"},{"n":4,"html":"데이터 마스킹(Masking)"}],"answer":[3],"explain":{"mine":"<p>데이터에 의도적으로 <b>노이즈(무작위 잡음)를 추가</b>해 개별 레코드의 식별을 막으면서 전체 통계적 특성은 유지하는 기법은 <b>차등 정보보호(Differential Privacy)</b>입니다. 애플·구글 등이 사용자 데이터 수집에 실제로 활용하는 기법입니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bbd","number":6,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>데이터 사이언티스트에게 요구되는 역량을 분류한 것으로 가장 적절한 것은?</p>","choices":[{"n":1,"html":"하드 스킬 - 문제 인식 및 정의를 통한 비즈니스 인사이트(통찰력) 도출"},{"n":2,"html":"소프트 스킬 - 수학·통계학 등의 이론적 지식"},{"n":3,"html":"하드 스킬 - 프로젝트에 참여한 팀원들에 대한 설득력"},{"n":4,"html":"소프트 스킬 - 커뮤니케이션 및 상호 협력"}],"answer":[4],"explain":{"mine":"<p><b>커뮤니케이션과 상호 협력은 소프트 스킬</b>이 맞습니다(4번). 통찰력 도출과 설득력도 소프트 스킬이고, 수학·통계학 이론 지식은 하드 스킬이므로 1~3번은 분류가 뒤바뀌었습니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bc2","number":7,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>다음 중 개인정보에 관한 설명으로 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"지문, 홍채, DNA 등 유전적 성질 및 인종에 대한 정보는 개인정보에 해당되지 않는다."},{"n":2,"html":"개인정보를 제3자에게 제공하려면 개인정보 주체로부터 별도의 동의를 받아야 한다."},{"n":3,"html":"개인정보를 처리할 때에는 개인정보 처리 방침을 사전에 공개하여야 한다."},{"n":4,"html":"개인정보는 이름, 주소와 같이 특정 개인을 식별할 수 있는 정보를 말한다."}],"answer":[1],"explain":{"mine":"<p>지문·홍채·DNA 같은 생체·유전 정보도 개인을 식별할 수 있는 <b>개인정보(민감정보)에 해당</b>합니다. '해당되지 않는다'는 1번이 옳지 않습니다. 제3자 제공 시 별도 동의, 처리방침 사전 공개는 맞는 설명입니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bc8","number":8,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>아래 자료의 데이터 유형으로 가장 알맞은 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><table class=\"q-tbl\"><tr><th>업종 구분</th><th>연도</th><th>평균 연봉(만 원)</th><th>지역</th><th>설립연도</th></tr><tr><td>1(제조)</td><td>2022</td><td>5,300</td><td>포항</td><td>1995</td></tr><tr><td>1(제조)</td><td>2023</td><td>5,600</td><td>포항</td><td>1995</td></tr><tr><td>2(IT서비스)</td><td>2022</td><td>7,100</td><td>성남</td><td>2003</td></tr><tr><td>2(IT서비스)</td><td>2023</td><td>7,400</td><td>성남</td><td>2003</td></tr><tr><td>3(금융)</td><td>2022</td><td>6,400</td><td>부산</td><td>1989</td></tr><tr><td>3(금융)</td><td>2023</td><td>6,800</td><td>부산</td><td>1989</td></tr></table></div>","choices":[{"n":1,"html":"대화형 데이터(Interactive Data)"},{"n":2,"html":"패널 데이터(Panel Data)"},{"n":3,"html":"횡단면 데이터(Cross-Sectional Data)"},{"n":4,"html":"시계열 데이터(Time Series Data)"}],"answer":[2],"explain":{"mine":"<p>여러 기업(횡단면 단위)을 <b>여러 연도에 걸쳐(시계열)</b> 반복 관측한 자료이므로 <b>패널 데이터</b>입니다. 한 시점의 여러 대상만 있으면 횡단면, 한 대상의 여러 시점만 있으면 시계열입니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bbc","number":9,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>다음 중 빅데이터의 3V 특징에 해당하지 않는 것은?</p>","choices":[{"n":1,"html":"Velocity(속도)"},{"n":2,"html":"Volume(규모)"},{"n":3,"html":"Variety(다양성)"},{"n":4,"html":"Value(가치)"}],"answer":[4],"explain":{"mine":"<p>빅데이터의 3V는 <b>Volume(규모), Variety(다양성), Velocity(속도)</b>입니다. Value(가치)는 3V에 나중에 추가되어 4V·5V로 확장될 때 포함되는 특성이라 3V에는 해당하지 않습니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bc6","number":10,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>다음 보기 가운데 비정형 데이터의 예시로 가장 거리가 먼 것은?</p>","choices":[{"n":1,"html":"SNS에 올린 개인 프로필 사진"},{"n":2,"html":"지니 음악"},{"n":3,"html":"틱톡 동영상"},{"n":4,"html":"반도체 판매량"}],"answer":[4],"explain":{"mine":"<p>사진·음악·동영상은 구조가 없는 <b>비정형 데이터</b>입니다. <b>반도체 판매량은 수치로 표현되는 정형 데이터</b>이므로 비정형의 예로 가장 거리가 멉니다(4번).</p>"}},{"id":"6a6a00621bbde79cd2c72bc0","number":11,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>확보한 데이터 중 일부에만 라벨(Label, 출력 또는 목표값)이 부여되어 있고 나머지에는 라벨이 존재하지 않는 상황에서 적용하기에 가장 적절한 데이터 학습 기법은?</p>","choices":[{"n":1,"html":"준지도 학습"},{"n":2,"html":"강화학습"},{"n":3,"html":"비지도 학습"},{"n":4,"html":"지도 학습"}],"answer":[1],"explain":{"mine":"<p>일부 데이터에만 라벨이 있는 상황에는 <b>준지도 학습(Semi-supervised Learning)</b>이 적합합니다. 라벨된 소량으로 학습을 시작하고 라벨 없는 대량의 데이터로 성능을 보강하는 방식입니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bcd","number":12,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>데이터의 품질을 높은 수준으로 유지·관리할 때 고려하는 핵심 평가 기준에 해당하지 않는 것은?</p>","choices":[{"n":1,"html":"시의성(Timeliness)"},{"n":2,"html":"정확성(Accuracy)"},{"n":3,"html":"불편의성(Unbiasedness)"},{"n":4,"html":"완전성(Completeness)"}],"answer":[3],"explain":{"mine":"<p>데이터 품질의 평가 기준은 정확성, 완전성, 일관성, 시의성(적시성), 유효성 등입니다. <b>불편의성(Unbiasedness)은 통계 추정량의 성질</b>(기댓값이 모수와 일치)이지 데이터 품질 기준이 아니므로 3번이 답입니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bc4","number":13,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>데이터 분석 마스터 플랜을 수립할 때 분석과제의 우선순위를 정하는 업무에서 고려할 요소로 가장 적합하지 않은 것은?</p>","choices":[{"n":1,"html":"비즈니스 성과 및 ROI"},{"n":2,"html":"실행 용이성"},{"n":3,"html":"전략적 중요도"},{"n":4,"html":"업무 내재화 적용 수준"}],"answer":[4],"explain":{"mine":"<p>분석과제 우선순위는 <b>전략적 중요도, 비즈니스 성과·ROI, 실행 용이성</b>을 기준으로 평가합니다. <b>업무 내재화 적용 수준은 우선순위가 아니라 이행 로드맵을 단계적으로 수립할 때</b> 고려하는 요소이므로 4번이 답입니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bbf","number":14,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>다음 보기 가운데 지도학습에 해당하는 사례로 가장 알맞은 것은?</p>","choices":[{"n":1,"html":"차원 축소"},{"n":2,"html":"회귀분석"},{"n":3,"html":"구글 딥마인드가 개발한 알파고"},{"n":4,"html":"K-means 클러스터링"}],"answer":[2],"explain":{"mine":"<p><b>회귀분석</b>은 정답(연속형 목표값)이 주어진 데이터로 학습하는 지도학습입니다. 차원 축소와 K-means는 라벨 없이 구조를 찾는 비지도학습, 알파고는 보상 기반의 강화학습입니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bc7","number":15,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>데이터의 유형에 관한 설명 중 가장 적절한 것은?</p>","choices":[{"n":1,"html":"자연어 처리에 활용되는 텍스트는 비정형 데이터의 대표적인 예이다."},{"n":2,"html":"테이블 형태로 정리된 데이터가 대표적인 반정형 데이터에 해당한다."},{"n":3,"html":"정형 데이터는 일반적으로 비정형 데이터에 비해 수집하기가 더 어렵다."},{"n":4,"html":"데이터 활용의 관점에서 정형 데이터는 비정형 데이터에 비해 그 가치가 매우 높다고 평가받는다."}],"answer":[1],"explain":{"mine":"<p>자연어 텍스트는 <b>비정형 데이터의 대표적인 예</b>가 맞습니다(1번). 테이블 형태는 정형 데이터이고(2번 오답), 정형 데이터가 수집이 더 어렵다고 볼 수 없으며(3번 오답), 데이터의 가치는 유형이 아니라 활용에 달려 있습니다(4번 오답).</p>"}},{"id":"6a6a00621bbde79cd2c72bc5","number":16,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>데이터를 수집할 때 고려해야 할 사항으로 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"수집 과정에서 개인정보가 활용되는지 여부"},{"n":2,"html":"데이터 분석에 사용할 기법의 난이도"},{"n":3,"html":"데이터 분석 과정에 드는 소요 비용"},{"n":4,"html":"해당 데이터의 수집 가능성"}],"answer":[2],"explain":{"mine":"<p>데이터 수집 단계에서는 수집 가능성, 수집·처리 비용, 개인정보 포함 여부, 데이터 품질 등을 고려합니다. <b>분석 기법의 난이도는 분석 단계의 문제</b>이지 수집 시 고려사항이 아니므로 2번이 답입니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bc1","number":17,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>아래 보기에서 설명하는 딥러닝 알고리즘으로 가장 적절한 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>서로 경쟁하는 두 개의 신경망을 훈련시켜 데이터를 생성하는 방식이다.</li><li>생성자는 실제와 흡사한 데이터를 만들어 내어 판별자가 가짜 데이터를 진짜로 인식하도록 유도한다.</li><li>판별자 또는 구별자는 입력된 데이터의 진위 여부를 구별하며, 잘못 인식하지 않도록 학습한다.</li><li>생성자와 판별자는 서로 적대적인 관계에 있다.</li></ul></div>","choices":[{"n":1,"html":"마스크드 오토인코더(Masked Autoencoders)"},{"n":2,"html":"합성곱 신경망(Convolutional Neural Network)"},{"n":3,"html":"생성적 적대 신경망(Generative Adversarial Network)"},{"n":4,"html":"순환 신경망(Recurrent Neural Network)"}],"answer":[3],"explain":{"mine":"<p>실제 같은 데이터를 만들어내는 <b>생성자(Generator)</b>와 진위를 가려내는 <b>판별자(Discriminator)</b>가 서로 경쟁하며 학습하는 구조는 <b>생성적 적대 신경망(GAN)</b>입니다. '적대적(Adversarial)'이라는 이름이 두 신경망의 경쟁 관계를 나타냅니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bcf","number":18,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>분산 파일 시스템(Distributed File System)에 관한 설명 중 가장 적절한 것은?</p>","choices":[{"n":1,"html":"다수의 마이크로프로세서를 활용한다."},{"n":2,"html":"여러 저장 장치가 단 하나의 서버에만 연결된 상태로 사용된다."},{"n":3,"html":"컴퓨터 네트워크를 통하여 여러 호스트 컴퓨터(PC)와 파일에 접근이 가능하다."},{"n":4,"html":"관계형 데이터베이스 및 SQL을 사용하지 않는다."}],"answer":[3],"explain":{"mine":"<p>분산 파일 시스템은 <b>네트워크를 통해 여러 호스트에 분산된 파일에 접근</b>할 수 있게 해주는 시스템입니다(3번). 저장 장치가 한 서버에만 연결된 것이 아니고(2번 오답), DBMS·SQL 사용 여부와는 별개의 개념입니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bbe","number":19,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>조직의 데이터 분석 성숙도 수준 가운데 아래 설명이 가리키는 단계는?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p>데이터 분석에 필요한 도구와 시스템을 구축하는 중이며, 데이터 분석은 일부 숙련된 담당자의 역량에 의존하고 있는 상태이다.</p></div>","choices":[{"n":1,"html":"활용"},{"n":2,"html":"도입"},{"n":3,"html":"확산"},{"n":4,"html":"최적화"}],"answer":[2],"explain":{"mine":"<p>분석 도구·시스템을 <b>구축하는 중</b>이고 일부 담당자 역량에 의존하는 상태는 성숙도 단계 중 <b>도입 단계</b>입니다. 활용(분석 결과를 업무에 적용), 확산(전사 관리·공유), 최적화(분석이 진화해 혁신 주도) 단계와 구분하세요.</p>"}},{"id":"6a6a00621bbde79cd2c72bc9","number":20,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>다음은 자동화 생산라인에서 생산한 부품B의 10,000개 당 불량품의 개수를 나타낸 것이다. 품질관리를 통해 불량율을 개선하려고 할 때 어떤 척도를 사용하는 것이 가장 적절한가?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><table class=\"q-tbl\"><tr><th>1월</th><th>2월</th><th>3월</th><th>4월</th><th>5월</th><th>6월</th></tr><tr><td>18개</td><td>25개</td><td>32개</td><td>47개</td><td>39개</td><td>28개</td></tr></table></div>","choices":[{"n":1,"html":"비율 척도"},{"n":2,"html":"서열 척도"},{"n":3,"html":"명목 척도"},{"n":4,"html":"등간 척도"}],"answer":[1],"explain":{"mine":"<p>불량품 '개수'는 절대영점(0개 = 불량이 전혀 없음)이 존재하고 곱셈·나눗셈 등 <b>사칙연산이 모두 의미를 갖는 비율 척도</b>입니다. 비율 척도여야 '불량률이 절반으로 줄었다' 같은 비율 비교가 가능합니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bd3","number":21,"category":"빅데이터 탐색","type":"choice","subject":"<p>아래에 제시된 네 개의 변수(X₁, X₂, X₃, X₄)의 박스플롯(Box-plot)에 관한 설명 중 가장 옳지 않은 것은?</p><div class=\"q-fig\"><svg class=\"q-fig__svg\" viewBox=\"0 0 600 360\" width=\"600\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"네 변수 X1부터 X4까지의 분포를 나타낸 박스플롯\"><g stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"60\" y1=\"30\" x2=\"60\" y2=\"310\"/><line x1=\"60\" y1=\"310\" x2=\"580\" y2=\"310\"/></g><g font-size=\"16\" fill=\"currentColor\" text-anchor=\"end\"><line x1=\"53\" y1=\"310\" x2=\"60\" y2=\"310\" stroke=\"currentColor\" stroke-width=\"2\"/><text x=\"45\" y=\"315\">0</text><line x1=\"53\" y1=\"275\" x2=\"60\" y2=\"275\" stroke=\"currentColor\" stroke-width=\"2\"/><text x=\"45\" y=\"280\">1</text><line x1=\"53\" y1=\"240\" x2=\"60\" y2=\"240\" stroke=\"currentColor\" stroke-width=\"2\"/><text x=\"45\" y=\"245\">2</text><line x1=\"53\" y1=\"205\" x2=\"60\" y2=\"205\" stroke=\"currentColor\" stroke-width=\"2\"/><text x=\"45\" y=\"210\">3</text><line x1=\"53\" y1=\"170\" x2=\"60\" y2=\"170\" stroke=\"currentColor\" stroke-width=\"2\"/><text x=\"45\" y=\"175\">4</text><line x1=\"53\" y1=\"135\" x2=\"60\" y2=\"135\" stroke=\"currentColor\" stroke-width=\"2\"/><text x=\"45\" y=\"140\">5</text><line x1=\"53\" y1=\"100\" x2=\"60\" y2=\"100\" stroke=\"currentColor\" stroke-width=\"2\"/><text x=\"45\" y=\"105\">6</text><line x1=\"53\" y1=\"65\" x2=\"60\" y2=\"65\" stroke=\"currentColor\" stroke-width=\"2\"/><text x=\"45\" y=\"70\">7</text><line x1=\"53\" y1=\"30\" x2=\"60\" y2=\"30\" stroke=\"currentColor\" stroke-width=\"2\"/><text x=\"45\" y=\"35\">8</text></g><g stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"140\" y1=\"152.5\" x2=\"140\" y2=\"187.5\"/><line x1=\"140\" y1=\"47.5\" x2=\"140\" y2=\"37\"/><line x1=\"125\" y1=\"187.5\" x2=\"155\" y2=\"187.5\"/><line x1=\"125\" y1=\"37\" x2=\"155\" y2=\"37\"/><rect x=\"115\" y=\"47.5\" width=\"50\" height=\"105\" fill=\"none\"/><line x1=\"115\" y1=\"93\" x2=\"165\" y2=\"93\" stroke-width=\"3\"/></g><text x=\"140\" y=\"340\" font-size=\"18\" fill=\"currentColor\" text-anchor=\"middle\">X₁</text><g stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"260\" y1=\"212\" x2=\"260\" y2=\"222.5\"/><line x1=\"260\" y1=\"198\" x2=\"260\" y2=\"187.5\"/><line x1=\"245\" y1=\"222.5\" x2=\"275\" y2=\"222.5\"/><line x1=\"245\" y1=\"187.5\" x2=\"275\" y2=\"187.5\"/><rect x=\"235\" y=\"198\" width=\"50\" height=\"14\" fill=\"none\"/><line x1=\"235\" y1=\"201.5\" x2=\"285\" y2=\"201.5\" stroke-width=\"3\"/><circle cx=\"260\" cy=\"247\" r=\"4\" fill=\"none\"/><circle cx=\"260\" cy=\"257.5\" r=\"4\" fill=\"none\"/><circle cx=\"260\" cy=\"163\" r=\"4\" fill=\"none\"/><circle cx=\"260\" cy=\"152.5\" r=\"4\" fill=\"none\"/></g><text x=\"260\" y=\"340\" font-size=\"18\" fill=\"currentColor\" text-anchor=\"middle\">X₂</text><g stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"380\" y1=\"275\" x2=\"380\" y2=\"303\"/><line x1=\"380\" y1=\"135\" x2=\"380\" y2=\"117.5\"/><line x1=\"365\" y1=\"303\" x2=\"395\" y2=\"303\"/><line x1=\"365\" y1=\"117.5\" x2=\"395\" y2=\"117.5\"/><rect x=\"355\" y=\"135\" width=\"50\" height=\"140\" fill=\"none\"/><line x1=\"355\" y1=\"163\" x2=\"405\" y2=\"163\" stroke-width=\"3\"/></g><text x=\"380\" y=\"340\" font-size=\"18\" fill=\"currentColor\" text-anchor=\"middle\">X₃</text><g stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"500\" y1=\"275\" x2=\"500\" y2=\"303\"/><line x1=\"500\" y1=\"205\" x2=\"500\" y2=\"170\"/><line x1=\"485\" y1=\"303\" x2=\"515\" y2=\"303\"/><line x1=\"485\" y1=\"170\" x2=\"515\" y2=\"170\"/><rect x=\"475\" y=\"205\" width=\"50\" height=\"70\" fill=\"none\"/><line x1=\"475\" y1=\"233\" x2=\"525\" y2=\"233\" stroke-width=\"3\"/></g><text x=\"500\" y=\"340\" font-size=\"18\" fill=\"currentColor\" text-anchor=\"middle\">X₄</text></svg></div>","choices":[{"n":1,"html":"X₄의 중앙값은 X₁의 중앙값에 비해 작다."},{"n":2,"html":"X₂의 분산은 X₃에 비해 작다."},{"n":3,"html":"X₂ 변수에는 이상값이 존재한다."},{"n":4,"html":"X₃의 평균값은 4에 근접한다."}],"answer":[4],"explain":{"mine":"<p>박스플롯은 중앙값·사분위수·이상값을 보여줄 뿐 <b>평균은 표시하지 않습니다</b>. 특히 X₃는 상자가 아래쪽(1~5)으로 넓게 퍼진 비대칭 분포라 평균이 중앙값(약 4.2)보다 작을 가능성이 커서, '평균값이 4에 근접한다'고 단정한 4번이 가장 옳지 않습니다. X₄ 중앙값(약 2.2) &lt; X₁ 중앙값(약 6.2), X₂의 좁은 상자(작은 분산), X₂의 이상값(동그라미)은 모두 그림과 일치합니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bda","number":22,"category":"빅데이터 탐색","type":"choice","subject":"<p>모분산이 σ²이고 표본분산이 S²일 때, 표본분산의 평균제곱오차(MSE, Mean Squared Error)는 얼마인가?</p>","choices":[{"n":1,"html":"2σ⁴/(n-1)"},{"n":2,"html":"σ⁴/n"},{"n":3,"html":"2σ⁴/n"},{"n":4,"html":"σ⁴/(n-1)"}],"answer":[1],"explain":{"mine":"<p>정규 모집단에서 표본분산 S²은 모분산의 불편추정량이므로 편향이 0이고, 따라서 MSE(S²) = Var(S²) = <b>2σ⁴/(n−1)</b>입니다(1번). (n−1)S²/σ²이 자유도 n−1인 카이제곱 분포를 따른다는 사실에서 유도됩니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bd0","number":23,"category":"빅데이터 탐색","type":"choice","subject":"<p>데이터 오류에 관한 설명 중 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"간섭 데이터는 특정한 패턴이나 주파수로 인해 발생하며 원래 신호와 겹칠 수 있는데, 이는 보통 노이즈 데이터로 취급한다."},{"n":2,"html":"노이즈 데이터는 데이터의 품질을 떨어뜨리고, 간섭 데이터는 신호의 정확성을 떨어뜨린다."},{"n":3,"html":"간섭 데이터는 주기적 패턴이나 규칙성을 지닌다."},{"n":4,"html":"노이즈 데이터는 무작위적 변동에 의해 발생한다."}],"answer":[1],"explain":{"mine":"<p>간섭 데이터는 특정 패턴·주파수를 가진 신호 왜곡으로, 무작위 변동인 노이즈와는 <b>구별되는 개념</b>입니다. '보통 노이즈 데이터로 취급한다'고 뭉뚱그린 1번이 옳지 않습니다. 노이즈=무작위(4번), 간섭=주기적 패턴(3번)이라는 구분이 핵심입니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bd7","number":24,"category":"빅데이터 탐색","type":"choice","subject":"<p>데이터를 수집한 결과, 관심 대상인 예측변수에서 클래스 불균형 문제가 나타났다. 이를 해결하는 방법으로 가장 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"과대표집"},{"n":2,"html":"군집"},{"n":3,"html":"과소표집"},{"n":4,"html":"클래스 가중치 조정"}],"answer":[2],"explain":{"mine":"<p>클래스 불균형 해결책은 과대표집(오버샘플링), 과소표집(언더샘플링), 클래스 가중치 조정 등입니다. <b>군집(클러스터링)은 비지도 학습 기법</b>이지 불균형 해결 방법이 아니므로 2번이 답입니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bdf","number":25,"category":"빅데이터 탐색","type":"choice","subject":"<p>모집단을 이질적인 집락들로 나눈 뒤 그중 몇 개의 집락을 무작위로 뽑아 표본으로 삼음으로써, 집단 내는 이질적이고 집단 간에는 동질적인 특징을 갖게 되는 확률표본추출방법은?</p>","choices":[{"n":1,"html":"군집표본추출"},{"n":2,"html":"층화표본추출"},{"n":3,"html":"계통표본추출"},{"n":4,"html":"단순무작위추출"}],"answer":[1],"explain":{"mine":"<p>모집단을 여러 집락으로 나눠 <b>일부 집락만 무작위로 뽑아 조사</b>하는 방법은 <b>군집표본추출</b>입니다. 이상적인 군집은 '집단 내부는 모집단처럼 이질적, 집단끼리는 서로 동질적'이어야 어느 군집을 뽑아도 모집단을 대표할 수 있습니다. 층화추출(층 내 동질·층 간 이질)과 정반대라는 점이 시험 포인트입니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bd2","number":26,"category":"빅데이터 탐색","type":"choice","subject":"<p>결측치 처리 기법에 관한 설명 중 가장 적절하지 않은 것은 무엇인가?</p>","choices":[{"n":1,"html":"완전분석법은 불완전한 자료를 전부 무시하고 완전하게 관측된 자료만을 사용하는 방법으로, 단순 대치 방법에 해당한다."},{"n":2,"html":"핫덱(Hot-deck) 기법은 동일하거나 유사한 성향의 자료를 여러 차례 사용해 가상 자료를 생성하고 대체 내 분산과 대체 사이의 분산을 추정하는 것으로, 다중 대치 방법 중 하나이다."},{"n":3,"html":"보삽법(Interpolation Method)에서는 시계열 자료의 결측치를 보완하기 위해 맥락적 사정 및 평가 방법을 활용할 수 있다."},{"n":4,"html":"외부 출처나 유사한 연구 결과를 활용해 결측치를 대치하는 콜드덱(Cold-deck) 기법은 단순 확률 대치 방법 중 하나이다."}],"answer":[2],"explain":{"mine":"<p>핫덱(Hot-deck)은 같은 조사 자료 안에서 유사한 응답자의 값을 가져와 결측을 채우는 <b>단순 대치 방법</b>입니다. '다중 대치 방법'이라고 한 2번이 옳지 않습니다. 다중 대치는 대치를 여러 번 반복해 여러 데이터셋을 만들어 결과를 종합하는 별도의 접근입니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bdd","number":27,"category":"빅데이터 탐색","type":"choice","subject":"<p>모든 데이터 값이 음수일 때, 그 결과를 해석하기가 가장 곤란한 기술 통계량은 다음 중 무엇인가?</p>","choices":[{"n":1,"html":"범위"},{"n":2,"html":"분산"},{"n":3,"html":"사분위수 범위"},{"n":4,"html":"변동계수"}],"answer":[4],"explain":{"mine":"<p><b>변동계수(CV) = 표준편차 ÷ 평균</b>인데, 모든 값이 음수면 평균이 음수가 되어 변동계수가 음수로 나오므로 산포의 크기로 해석하기 곤란해집니다(4번). 범위·분산·IQR은 값의 부호와 무관하게 양수로 계산됩니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bd4","number":28,"category":"빅데이터 탐색","type":"choice","subject":"<p>절대영점을 가지며 사칙연산을 적용할 수 있는 척도는 다음 중 어느 것인가?</p>","choices":[{"n":1,"html":"비율 척도(Ratio Scale)"},{"n":2,"html":"서열 척도(Ordinal Scale)"},{"n":3,"html":"명목 척도(Nominal Scale)"},{"n":4,"html":"간격 척도(Interval Scale)"}],"answer":[1],"explain":{"mine":"<p>절대영점이 있고 사칙연산이 모두 가능한 척도는 <b>비율 척도</b>입니다(무게, 길이, 소득 등). 간격 척도(온도 ℃ 등)는 덧셈·뺄셈만 의미가 있고 절대영점이 없어 '두 배' 같은 비율 비교가 불가능하다는 점에서 다릅니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bd1","number":29,"category":"빅데이터 탐색","type":"choice","subject":"<p>다음 설명에 해당하는, 엔터프라이즈 데이터웨어하우스(EDW, Enterprise Data Warehouse)에 데이터가 저장되기 전 단계에서 활용되는 저장 장소는 무엇인가?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p>EDW에 데이터를 적재하기 전에 운영 시스템의 데이터를 임시로 보관하는 장소로, 운영 시스템의 이력성 데이터를 담는다. EDW를 보완하여 의사결정 지원에 활용되며, 주로 운영 보고(Report), 제어, 의사결정, 데이터에 대한 추가 작업을 목적으로 여러 소스의 데이터를 통합하도록 설계된 데이터베이스이다. 대량으로 축적되는 일반적인 데이터와 달리, 실시간 또는 실시간 근접(Near Real Time) 데이터, 혹은 저수준 또는 원자성 데이터를 담을 수 있도록 설계된다.</p></div>","choices":[{"n":1,"html":"Data Mart(DM)"},{"n":2,"html":"Operational Data Store(ODS)"},{"n":3,"html":"Online Analytical Processing(OLAP)"},{"n":4,"html":"Extract, Transform, Load(ETL)"}],"answer":[2],"explain":{"mine":"<p>EDW에 적재하기 전 운영 시스템의 데이터를 임시로 보관하고, 실시간·근실시간의 원자성 데이터를 담아 운영 보고와 의사결정을 지원하는 저장소는 <b>ODS(Operational Data Store)</b>입니다. 데이터 마트는 DW 이후의 주제별 부분집합이고, ETL은 저장소가 아니라 이동·변환 과정입니다.</p>"}},{"id":"6a6a00621bbde79cd2c72be0","number":30,"category":"빅데이터 탐색","type":"choice","subject":"<p>확률분포의 성질에 관한 다음 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"정규분포의 모양은 모수인 평균과 표준편차에 따라 결정된다."},{"n":2,"html":"포아송분포에서 분산은 평균의 제곱과 동일하다."},{"n":3,"html":"초기하분포는 N개의 모집단에서 비복원추출로 n개를 뽑을 때 k번 성공할 확률을 나타내는 분포이다."},{"n":4,"html":"서로 독립인 k개의 표준정규분포를 합하면 카이제곱 분포를 따른다."}],"answer":[2],"explain":{"mine":"<p>포아송분포는 <b>평균과 분산이 모두 λ로 같습니다</b>. '분산이 평균의 제곱'이라는 2번이 옳지 않습니다. 참고로 4번은 표준정규분포들의 '제곱합'이 카이제곱 분포를 따른다는 의미로 이해해야 정확합니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bdb","number":31,"category":"빅데이터 탐색","type":"choice","subject":"<p>첨도에 관한 설명 중 가장 옳은 것은 무엇인가?</p>","choices":[{"n":1,"html":"첨도의 단위는 평균의 단위와 같다."},{"n":2,"html":"첨도는 0의 값을 가지는 것이 불가능하다."},{"n":3,"html":"첨도는 자료의 분포 모양이 어느 방향으로 얼마나 기울어져 있는지를 살펴보는 통계량이다."},{"n":4,"html":"첨도 통계량은 언제나 양수의 값을 가진다."}],"answer":[1],"explain":{"mine":"<p>소거법으로 접근합니다. 첨도가 0이 되는 것은 가능하고(초과첨도 기준으로 정규분포 = 0, 2번 오답), 분포의 기울어진 방향을 보는 것은 왜도(3번 오답), 초과첨도는 음수도 가능합니다(4번 오답 — 균등분포 등). 남는 1번이 답으로 복원되어 있으나, 엄밀히는 첨도가 표준화된 무차원 통계량이라 '평균의 단위와 같다'는 표현도 정확하지 않습니다 — 복원 과정에서 문구가 다듬어지지 못한 문항으로 보이니 2·3·4번이 틀린 이유 중심으로 정리해 두세요.</p>"}},{"id":"6a6a00621bbde79cd2c72bd9","number":32,"category":"빅데이터 탐색","type":"choice","subject":"<p>아래 그림처럼 분포가 왼쪽으로 치우친 형태를 보일 때, 왜도와 최빈값, 중위수, 평균값 간의 크기 관계를 바르게 나타낸 것은?</p><div class=\"q-fig\"><svg class=\"q-fig__svg\" viewBox=\"0 0 560 320\" width=\"560\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"막대 봉우리가 왼쪽 부근에 있고 오른쪽으로 갈수록 막대가 낮아지며 길게 이어지는 히스토그램\"><defs><marker id=\"axArw\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\"><path d=\"M0 0L10 5L0 10z\" fill=\"currentColor\"/></marker></defs><line x1=\"70\" y1=\"270\" x2=\"70\" y2=\"28\" stroke=\"currentColor\" stroke-width=\"1.6\" marker-end=\"url(#axArw)\"/><line x1=\"70\" y1=\"270\" x2=\"548\" y2=\"270\" stroke=\"currentColor\" stroke-width=\"1.6\" marker-end=\"url(#axArw)\"/><line x1=\"64\" y1=\"215\" x2=\"70\" y2=\"215\" stroke=\"currentColor\" stroke-width=\"1.6\"/><text x=\"58\" y=\"220\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"end\">20</text><line x1=\"64\" y1=\"160\" x2=\"70\" y2=\"160\" stroke=\"currentColor\" stroke-width=\"1.6\"/><text x=\"58\" y=\"165\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"end\">40</text><line x1=\"64\" y1=\"105\" x2=\"70\" y2=\"105\" stroke=\"currentColor\" stroke-width=\"1.6\"/><text x=\"58\" y=\"110\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"end\">60</text><line x1=\"64\" y1=\"50\" x2=\"70\" y2=\"50\" stroke=\"currentColor\" stroke-width=\"1.6\"/><text x=\"58\" y=\"55\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"end\">80</text><text x=\"58\" y=\"275\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"end\">0</text><text x=\"22\" y=\"150\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\" transform=\"rotate(-90 22 150)\">Frequency</text><line x1=\"80\" y1=\"270\" x2=\"80\" y2=\"276\" stroke=\"currentColor\" stroke-width=\"1.6\"/><text x=\"80\" y=\"294\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"middle\">0</text><line x1=\"208\" y1=\"270\" x2=\"208\" y2=\"276\" stroke=\"currentColor\" stroke-width=\"1.6\"/><text x=\"208\" y=\"294\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"middle\">40</text><line x1=\"336\" y1=\"270\" x2=\"336\" y2=\"276\" stroke=\"currentColor\" stroke-width=\"1.6\"/><text x=\"336\" y=\"294\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"middle\">80</text><line x1=\"464\" y1=\"270\" x2=\"464\" y2=\"276\" stroke=\"currentColor\" stroke-width=\"1.6\"/><text x=\"464\" y=\"294\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"middle\">120</text><rect x=\"80\" y=\"220.5\" width=\"32\" height=\"49.5\" fill=\"currentColor\" fill-opacity=\"0.15\" stroke=\"currentColor\" stroke-width=\"1.4\"/><rect x=\"112\" y=\"118.75\" width=\"32\" height=\"151.25\" fill=\"currentColor\" fill-opacity=\"0.15\" stroke=\"currentColor\" stroke-width=\"1.4\"/><rect x=\"144\" y=\"55.5\" width=\"32\" height=\"214.5\" fill=\"currentColor\" fill-opacity=\"0.15\" stroke=\"currentColor\" stroke-width=\"1.4\"/><rect x=\"176\" y=\"77.5\" width=\"32\" height=\"192.5\" fill=\"currentColor\" fill-opacity=\"0.15\" stroke=\"currentColor\" stroke-width=\"1.4\"/><rect x=\"208\" y=\"127\" width=\"32\" height=\"143\" fill=\"currentColor\" fill-opacity=\"0.15\" stroke=\"currentColor\" stroke-width=\"1.4\"/><rect x=\"240\" y=\"165.5\" width=\"32\" height=\"104.5\" fill=\"currentColor\" fill-opacity=\"0.15\" stroke=\"currentColor\" stroke-width=\"1.4\"/><rect x=\"272\" y=\"195.75\" width=\"32\" height=\"74.25\" fill=\"currentColor\" fill-opacity=\"0.15\" stroke=\"currentColor\" stroke-width=\"1.4\"/><rect x=\"304\" y=\"217.75\" width=\"32\" height=\"52.25\" fill=\"currentColor\" fill-opacity=\"0.15\" stroke=\"currentColor\" stroke-width=\"1.4\"/><rect x=\"336\" y=\"234.25\" width=\"32\" height=\"35.75\" fill=\"currentColor\" fill-opacity=\"0.15\" stroke=\"currentColor\" stroke-width=\"1.4\"/><rect x=\"368\" y=\"245.25\" width=\"32\" height=\"24.75\" fill=\"currentColor\" fill-opacity=\"0.15\" stroke=\"currentColor\" stroke-width=\"1.4\"/><rect x=\"400\" y=\"253.5\" width=\"32\" height=\"16.5\" fill=\"currentColor\" fill-opacity=\"0.15\" stroke=\"currentColor\" stroke-width=\"1.4\"/><rect x=\"432\" y=\"259\" width=\"32\" height=\"11\" fill=\"currentColor\" fill-opacity=\"0.15\" stroke=\"currentColor\" stroke-width=\"1.4\"/><rect x=\"464\" y=\"261.75\" width=\"32\" height=\"8.25\" fill=\"currentColor\" fill-opacity=\"0.15\" stroke=\"currentColor\" stroke-width=\"1.4\"/><rect x=\"496\" y=\"264.5\" width=\"32\" height=\"5.5\" fill=\"currentColor\" fill-opacity=\"0.15\" stroke=\"currentColor\" stroke-width=\"1.4\"/></svg></div>","choices":[{"n":1,"html":"왜도&lt;0, 최빈값&gt;중위수&gt;평균값"},{"n":2,"html":"왜도&gt;0, 최빈값&lt;중위수&lt;평균값"},{"n":3,"html":"왜도&gt;0, 최빈값&gt;중위수&gt;평균값"},{"n":4,"html":"왜도&lt;0, 최빈값&lt;중위수&lt;평균값"}],"answer":[2],"explain":{"mine":"<p>봉우리가 왼쪽(작은 값)에 몰려 있고 오른쪽으로 꼬리가 긴 분포는 <b>양의 왜도(왜도&gt;0)</b>이며, 크기 관계는 <b>최빈값 &lt; 중위수 &lt; 평균값</b>입니다(2번). 오른쪽 꼬리의 큰 값들이 평균을 끌어올리기 때문입니다.</p>"}},{"id":"6a6a00621bbde79cd2c72be1","number":33,"category":"빅데이터 탐색","type":"choice","subject":"<p>확률변수 X가 E(X)=1/2, Var(X)=1/4를 만족한다고 할 때, X의 기댓값은 얼마인가?</p>","choices":[{"n":1,"html":"1/4"},{"n":2,"html":"1/2"},{"n":3,"html":"3/4"},{"n":4,"html":"1"}],"answer":[2],"explain":{"mine":"<p>문제에서 이미 <b>E(X) = 1/2</b>로 주어졌으므로 기댓값은 그대로 1/2입니다(2번). 분산 정보는 판단을 흐리기 위한 함정으로, 기댓값 계산에는 필요하지 않습니다.</p>"}},{"id":"6a6a00621bbde79cd2c72be3","number":34,"category":"빅데이터 탐색","type":"choice","subject":"<p>회귀분석에서 회귀계수에 대한 분산분석을 통해 유의성을 검정하고자 할 때, 이때 사용하는 검정통계량의 분포와 검정 방법을 올바르게 설명한 것은? (단, 검정통계량으로부터 구한 유의확률은 p-value이며 유의수준은 α로 한다)</p>","choices":[{"n":1,"html":"F-분포를 따르며, p-value가 α를 초과하면 귀무가설을 기각"},{"n":2,"html":"카이제곱 분포를 따르며, p-value가 α를 초과하면 귀무가설을 기각"},{"n":3,"html":"카이제곱 분포를 따르며, p-value가 α 미만이면 귀무가설을 기각"},{"n":4,"html":"F-분포를 따르며, p-value가 α 미만이면 귀무가설을 기각"}],"answer":[4],"explain":{"mine":"<p>회귀계수의 유의성을 분산분석으로 검정할 때 검정통계량은 <b>F-분포</b>를 따르고(MSR/MSE), <b>p-value가 유의수준 α보다 작으면 귀무가설(회귀계수 = 0)을 기각</b>합니다(4번). p-value가 α를 초과하면 기각하지 못한다는 점에서 1·2번은 반대로 서술되었습니다.</p>"}},{"id":"6a6a00621bbde79cd2c72be2","number":35,"category":"빅데이터 탐색","type":"choice","subject":"<p>달빛동에 사는 주민 1,000명을 대상으로 조사한 결과, 이 중 100명이 실업자인 것으로 나타났다. 조사 대상 주민 중 실업자 수의 모평균 신뢰구간에 관한 설명 중 가장 옳지 않은 것은?</p>","choices":[{"n":1,"html":"신뢰수준=95%에서 표본으로 뽑힌 주민 중 실업자 수가 100명인 경우보다 200명인 경우에 신뢰구간이 더 좁다."},{"n":2,"html":"90% 신뢰구간이 95% 신뢰구간보다 더 좁다."},{"n":3,"html":"99% 신뢰구간이 95% 신뢰구간보다 더 넓다."},{"n":4,"html":"신뢰수준=95%에서 주민 수가 1,000명인 경우보다 2,000명인 경우에 신뢰구간이 더 좁다."}],"answer":[1],"explain":{"mine":"<p>비율 추정의 신뢰구간 폭은 √(p̂(1−p̂))에 비례합니다. p̂=0.1일 때 0.1×0.9=0.09, p̂=0.2일 때 0.2×0.8=0.16이므로 실업자가 200명(p̂=0.2)인 경우 구간이 <b>더 넓어집니다</b>. '더 좁다'고 한 1번이 옳지 않습니다. 신뢰수준이 높을수록 구간이 넓어지고, 표본이 클수록 좁아진다는 2~4번은 맞습니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bd5","number":36,"category":"빅데이터 탐색","type":"choice","subject":"<p>주성분 분석에 관한 다음 설명 중 옳은 것을 모두 고른 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>(가) 기존 변수들의 선형 변환을 통해 주성분이라는 새로운 변수를 만들어낸다.</li><li>(나) 주성분 분석으로 만들어진 주성분들은 서로 독립적인 관계를 갖는다.</li><li>(다) 데이터의 차원을 축소하여 차원의 저주 문제를 완화하는 데 활용된다.</li><li>(라) 독립성, 등분산성, 정규성을 사전에 가정한다.</li></ul></div>","choices":[{"n":1,"html":"(나), (다)"},{"n":2,"html":"(가), (나), (다)"},{"n":3,"html":"(가), (다), (라)"},{"n":4,"html":"(가)"}],"answer":[2],"explain":{"mine":"<p>(가) 주성분은 기존 변수의 선형 변환, (나) 주성분들끼리는 직교(무상관), (다) 차원의 저주 완화 — 모두 맞습니다. (라)는 틀렸습니다. 독립성·등분산성·정규성은 <b>회귀분석의 가정</b>이지 PCA의 전제 조건이 아닙니다. 따라서 (가)(나)(다)인 2번이 답입니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bdc","number":37,"category":"빅데이터 탐색","type":"choice","subject":"<p>다음 자료(H기업의 월별 매출액)는 어떤 유형에 해당하는가?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><table class=\"q-tbl\"><tr><td>1월</td><td>2월</td><td>3월</td><td>4월</td><td>5월</td><td>6월</td></tr><tr><td>150</td><td>170</td><td>190</td><td>185</td><td>210</td><td>230</td></tr><tr><td>7월</td><td>8월</td><td>9월</td><td>10월</td><td>11월</td><td>12월</td></tr><tr><td>250</td><td>245</td><td>270</td><td>290</td><td>310</td><td>340</td></tr></table></div>","choices":[{"n":1,"html":"횡단면 자료"},{"n":2,"html":"준정형 자료"},{"n":3,"html":"시계열 자료"},{"n":4,"html":"패널 자료"}],"answer":[3],"explain":{"mine":"<p>하나의 대상(H기업)을 <b>시간 순서(월별)로 관측</b>한 자료이므로 <b>시계열 자료</b>입니다. 여러 대상을 한 시점에 본 것이 횡단면, 여러 대상을 여러 시점에 걸쳐 본 것이 패널 자료입니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bd8","number":38,"category":"빅데이터 탐색","type":"choice","subject":"<p>어떤 모집단의 두 속성 A, B 간 독립성과 상관계수의 관계를 설명한 것 중 옳은 것은?</p>","choices":[{"n":1,"html":"모집단 상관계수가 0이라면 A와 B는 서로 독립이다."},{"n":2,"html":"표본집단 상관계수가 0이라면 A와 B는 서로 독립이다."},{"n":3,"html":"A와 B가 서로 독립이라면 표본집단 상관계수는 0이다."},{"n":4,"html":"A와 B가 서로 독립이라면 모집단 상관계수는 0이다."}],"answer":[4],"explain":{"mine":"<p>독립이면 모집단 상관계수는 반드시 0입니다(4번). 그러나 역은 성립하지 않고(상관 0이어도 비선형 종속 가능 — 1번 오답), 표본 상관계수는 독립이어도 표본 변동 때문에 정확히 0이 되지는 않습니다(2·3번 오답).</p>"}},{"id":"6a6a00621bbde79cd2c72bde","number":39,"category":"빅데이터 탐색","type":"choice","subject":"<p>아래에 제시된 로지스틱 회귀분석 모형에 관한 설명 중 옳지 않은 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>P(Y=1)=p, P(Y=0)=1-P(Y=1)=1-p이다.</li><li>log(p/(1-p))=a+bx 식을 이용하여 회귀계수(a)와 상수항(b)을 예측한다.</li></ul></div>","choices":[{"n":1,"html":"오즈비(Odds Ratio)는 p/(1-p)로 정의된다."},{"n":2,"html":"a=0, b=0이면 p=1이다."},{"n":3,"html":"P(Y=1)=1/(1+exp(-a-bx))로 표현할 수 있다."},{"n":4,"html":"a=0, b=0이면 P(Y=0)=1/2이다."}],"answer":[2],"explain":{"mine":"<p>a=0, b=0이면 log(p/(1−p)) = 0이므로 p/(1−p) = 1, 즉 <b>p = 1/2</b>입니다. 'p=1'이라고 한 2번이 옳지 않습니다. 이때 P(Y=0) = 1/2이라는 4번, 로지스틱 함수 표현(3번)은 맞습니다.</p>"}},{"id":"6a6a00621bbde79cd2c72bd6","number":40,"category":"빅데이터 탐색","type":"choice","subject":"<p>차원축소 기법에 관한 설명 중 가장 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"다차원 척도법(MDS)을 활용해 고차원 데이터를 저차원 공간에 투영함으로써 데이터 간 유사성을 시각화한다."},{"n":2,"html":"특이값 분해 방법은 PCA와 비교할 때 큰 행렬에서 SVD를 계산하는 데 많은 시간과 저장공간을 필요로 한다."},{"n":3,"html":"t-SNE 기법을 활용해 주어진 비용함수를 최소화 또는 최대화하는 문제를 해결한다."},{"n":4,"html":"주성분 분석(PCA)은 선형적인 차원축소 기법으로, 데이터의 분산이 최대가 되는 방향으로 차원을 축소한다."}],"answer":[3],"explain":{"mine":"<p>t-SNE는 고차원과 저차원 분포 간의 KL 발산이라는 비용함수를 <b>최소화</b>하는 기법입니다. '최소화 또는 최대화하는 문제를 해결한다'고 한 3번이 가장 부정확합니다. MDS의 유사성 시각화, PCA의 최대 분산 방향 축소 설명은 맞습니다.</p>"}},{"id":"6a6a00631bbde79cd2c72be9","number":41,"category":"빅데이터 모델링","type":"choice","subject":"<p>1차원 데이터에 대한 아래의 분류 문제를 서포트벡터머신 기법으로 해결하려고 한다. 이때 사용할 초평면으로 가장 적절한 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>분류 데이터 : a=(-2, 0), b=(-3, 0), c=(-4, 0), d=(2, 0), e=(3, 0)</li><li>(a, b, c, d)는 레이블=0으로 분류</li><li>e는 레이블=1로 분류</li></ul></div>","choices":[{"n":1,"html":"x=2.5"},{"n":2,"html":"x=√2.5"},{"n":3,"html":"x=2"},{"n":4,"html":"x=-0.5"}],"answer":[1],"explain":{"mine":"<p>1차원에서 레이블 0의 최댓값은 x=2(점 d), 레이블 1의 최솟값은 x=3(점 e)입니다. SVM은 두 클래스 사이의 마진이 최대가 되는 경계를 찾으므로 두 점의 <b>정중앙인 x=2.5</b>가 최적 초평면입니다(1번).</p>"}},{"id":"6a6a00631bbde79cd2c72bee","number":42,"category":"빅데이터 모델링","type":"choice","subject":"<p>딥러닝 분석에서 활용되는 seq2seq(sequence-to-sequence) 모델에 관한 설명 중 옳은 것을 모두 고른 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>(가) 순환신경망 구조에서 사용되는 입력 시퀀스에 대하여 길이가 다양한 시퀀스 데이터를 처리할 수 있다.</li><li>(나) 입력 시퀀스의 길이와 무관하게 모형의 성능이나 품질은 동일하게 유지된다.</li><li>(다) 인코더-디코더 구조로 이루어져 있으며, 벡터 형태의 컨텍스트 텍스트가 만들어진다.</li></ul></div>","choices":[{"n":1,"html":"(가), (다)"},{"n":2,"html":"(가)"},{"n":3,"html":"(나), (다)"},{"n":4,"html":"(가), (나), (다)"}],"answer":[1],"explain":{"mine":"<p>(가) seq2seq는 가변 길이 시퀀스를 처리할 수 있고, (다) 인코더-디코더 구조로 입력을 고정 크기의 컨텍스트 벡터로 요약합니다 — 모두 맞습니다. (나)는 틀렸습니다. 긴 시퀀스일수록 고정 크기 벡터에 정보를 압축하는 병목 때문에 <b>성능이 저하</b>되며, 이를 보완하려고 어텐션이 도입되었습니다.</p>"}},{"id":"6a6a00631bbde79cd2c72bf0","number":43,"category":"빅데이터 모델링","type":"choice","subject":"<p>다음 그림과 같은 인공신경망의 학습과정에서 활성화 함수로 항등함수(Identity Function)를 사용하여 출력값을 계산할 때, 해당 노드의 출력값(Output Y)은 얼마인가?</p><div class=\"q-fig\"><svg class=\"q-fig__svg\" viewBox=\"0 0 760 400\" width=\"760\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"두 입력 X1·X2, 은닉 노드 H1·H2, 출력 노드 Y와 가중치 라벨이 표시된 인공신경망 그림\"><defs><marker id=\"arw2\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"8\" markerHeight=\"8\" orient=\"auto-start-reverse\"><path d=\"M0 0L10 5L0 10z\" fill=\"currentColor\"/></marker></defs><text x=\"130\" y=\"38\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"middle\" font-style=\"italic\">Input X</text><text x=\"640\" y=\"125\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"middle\" font-style=\"italic\">Output Y</text><text x=\"45\" y=\"96\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"middle\">1</text><line x1=\"60\" y1=\"90\" x2=\"96\" y2=\"90\" stroke=\"currentColor\" stroke-width=\"1.6\" marker-end=\"url(#arw2)\"/><text x=\"45\" y=\"276\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"middle\">2</text><line x1=\"60\" y1=\"270\" x2=\"96\" y2=\"270\" stroke=\"currentColor\" stroke-width=\"1.6\" marker-end=\"url(#arw2)\"/><line x1=\"160\" y1=\"91\" x2=\"356\" y2=\"99\" stroke=\"currentColor\" stroke-width=\"1.6\" marker-end=\"url(#arw2)\"/><line x1=\"155\" y1=\"106\" x2=\"362\" y2=\"242\" stroke=\"currentColor\" stroke-width=\"1.6\" marker-end=\"url(#arw2)\"/><line x1=\"155\" y1=\"254\" x2=\"362\" y2=\"128\" stroke=\"currentColor\" stroke-width=\"1.6\" marker-end=\"url(#arw2)\"/><line x1=\"160\" y1=\"269\" x2=\"356\" y2=\"261\" stroke=\"currentColor\" stroke-width=\"1.6\" marker-end=\"url(#arw2)\"/><line x1=\"419\" y1=\"109\" x2=\"608\" y2=\"170\" stroke=\"currentColor\" stroke-width=\"1.6\" marker-end=\"url(#arw2)\"/><line x1=\"419\" y1=\"251\" x2=\"608\" y2=\"189\" stroke=\"currentColor\" stroke-width=\"1.6\" marker-end=\"url(#arw2)\"/><circle cx=\"130\" cy=\"90\" r=\"30\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/><text x=\"130\" y=\"96\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"middle\" font-style=\"italic\">X1</text><circle cx=\"130\" cy=\"270\" r=\"30\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/><text x=\"130\" y=\"276\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"middle\" font-style=\"italic\">X2</text><circle cx=\"390\" cy=\"100\" r=\"30\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/><text x=\"390\" y=\"106\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"middle\" font-style=\"italic\">H1</text><circle cx=\"390\" cy=\"260\" r=\"30\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/><text x=\"390\" y=\"266\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"middle\" font-style=\"italic\">H2</text><circle cx=\"640\" cy=\"180\" r=\"30\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/><text x=\"640\" y=\"186\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"middle\" font-style=\"italic\">Y</text><text x=\"255\" y=\"80\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\" font-style=\"italic\">W1=10</text><text x=\"230\" y=\"145\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\" font-style=\"italic\">W3=2</text><text x=\"250\" y=\"220\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\" font-style=\"italic\">W2=3</text><text x=\"255\" y=\"295\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\" font-style=\"italic\">W4=1</text><text x=\"510\" y=\"120\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\" font-style=\"italic\">HW5=2</text><text x=\"510\" y=\"250\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\" font-style=\"italic\">HW6=-3</text><text x=\"380\" y=\"350\" font-size=\"14.5\" fill=\"currentColor\" text-anchor=\"middle\" font-style=\"italic\">Output Y = X × W × HW</text><text x=\"380\" y=\"378\" font-size=\"14.5\" fill=\"currentColor\" text-anchor=\"middle\" font-style=\"italic\">Y = ((X1 X2)×(W1 W2) (W3 W4))×(HW5 HW6)</text></svg></div>","choices":[{"n":1,"html":"17"},{"n":2,"html":"18"},{"n":3,"html":"19"},{"n":4,"html":"20"}],"answer":[4],"explain":{"mine":"<p>은닉층: H1 = 1×10 + 2×3 = 16, H2 = 1×2 + 2×1 = 4. 출력: Y = 16×2 + 4×(−3) = 32 − 12 = <b>20</b>입니다. 활성화 함수가 항등함수이므로 가중합이 그대로 전달됩니다.</p>"}},{"id":"6a6a00621bbde79cd2c72be4","number":44,"category":"빅데이터 모델링","type":"choice","subject":"<p>데이터 분석으로 당면한 문제를 풀려고 한다. 분석대상이 무엇인지 미리 알고 있고 분석 방법 역시 알고 있는 상황에서 적용하기에 옳은 방법은?</p>","choices":[{"n":1,"html":"최적화(Optimization)"},{"n":2,"html":"통찰(Insight)"},{"n":3,"html":"솔루션(Solution)"},{"n":4,"html":"발견(Discovery)"}],"answer":[1],"explain":{"mine":"<p>분석대상(What)과 분석방법(How)을 <b>모두 알고 있는</b> 경우에는 <b>최적화(Optimization)</b>를 수행합니다. 대상만 알면 솔루션, 방법만 알면 통찰, 둘 다 모르면 발견입니다.</p>"}},{"id":"6a6a00631bbde79cd2c72bec","number":45,"category":"빅데이터 모델링","type":"choice","subject":"<p>아래 조건을 참고하여, 불량품이 하나 발견되었을 때 그 불량품이 A공정에서 만들어졌을 확률을 베이지안 기법으로 계산하시오.</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>전체 공정에서 A공정이 차지하는 비율은 50%, B공정은 30%, C공정은 20%이다.</li><li>공정별 불량률은 A공정 1%, B공정 2%, C공정 3%이다.</li></ul></div>","choices":[{"n":1,"html":"6/17"},{"n":2,"html":"5/12"},{"n":3,"html":"1/2"},{"n":4,"html":"5/17"}],"answer":[4],"explain":{"mine":"<p>전체 불량률 = 0.5×0.01 + 0.3×0.02 + 0.2×0.03 = 0.005 + 0.006 + 0.006 = 0.017. 베이즈 정리로 P(A|불량) = 0.005 / 0.017 = <b>5/17</b>입니다(4번). A공정이 생산량은 가장 많지만 불량률이 낮아 절반에 못 미치는 확률이 나옵니다.</p>"}},{"id":"6a6a00631bbde79cd2c72bf4","number":46,"category":"빅데이터 모델링","type":"choice","subject":"<p>텍스트 마이닝에서 활용되는 자연어 처리 기법에 관한 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"Stop words removal : 유용하지 않고 큰 의미가 없는 단어를 제거함"},{"n":2,"html":"Tokenization : 긴 형태의 텍스트를 토큰이라 불리는 문장 및 단어 단위로 나눔"},{"n":3,"html":"Stemming : 문장을 의미있는 토큰으로 분해하여 문장 구조를 생성함"},{"n":4,"html":"Pos tagging : 문장 내 각 단어의 품사를 결정함"}],"answer":[3],"explain":{"mine":"<p>Stemming(어간 추출)은 running→run처럼 단어의 <b>어형 변화를 잘라내어 어간만 남기는</b> 처리입니다. '문장을 토큰으로 분해해 문장 구조를 생성한다'는 3번은 토큰화·구문 분석에 대한 설명이므로 옳지 않습니다.</p>"}},{"id":"6a6a00631bbde79cd2c72bf2","number":47,"category":"빅데이터 모델링","type":"choice","subject":"<p>활성화 함수 중 하나인 쌍곡선 탄젠트(Hyperbolic Tangent)에 관한 설명 가운데 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"S자형 곡선 형태로, 입력 값이 0 근처일 때는 거의 선형적으로 변환된다."},{"n":2,"html":"입력값에 비선형성을 부여한다."},{"n":3,"html":"시그모이드 함수와 출력 범위가 동일하다."},{"n":4,"html":"데이터 분석 모델이 보다 복잡한 패턴을 학습하는 것을 가능하게 한다."}],"answer":[3],"explain":{"mine":"<p>tanh의 출력 범위는 <b>−1 ~ 1</b>이고 시그모이드는 <b>0 ~ 1</b>이라 서로 다릅니다. '출력 범위가 동일하다'는 3번이 옳지 않습니다. S자형 곡선, 0 근처의 선형성, 비선형성 부여는 맞는 설명입니다.</p>"}},{"id":"6a6a00631bbde79cd2c72bea","number":48,"category":"빅데이터 모델링","type":"choice","subject":"<p>군집분석에서 군집 간 거리를 측정하는 방법에 관한 설명 중 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"와드 연결법 : 두 군집 사이 거리의 평균"},{"n":2,"html":"중심 연결법 : 두 군집의 중심 간의 거리"},{"n":3,"html":"단일 연결법 : 두 군집 사이 거리들 가운데 최솟값"},{"n":4,"html":"완전 연결법 : 두 군집 사이 거리들 가운데 최댓값"}],"answer":[1],"explain":{"mine":"<p><b>와드 연결법은 거리 평균이 아니라 병합 시 오차제곱합(SSE)의 증가가 최소</b>가 되는 군집을 합치는 방법입니다(1번이 옳지 않음). '두 군집 사이 거리의 평균'은 평균 연결법에 대한 설명입니다. 단일(최솟값)·완전(최댓값)·중심(중심 간 거리) 연결법 설명은 맞습니다.</p>"}},{"id":"6a6a00621bbde79cd2c72be6","number":49,"category":"빅데이터 모델링","type":"choice","subject":"<p>다음은 단순회귀분석 결과에서 모형의 유의성 검정을 위해 만든 분산분석표(ANOVA, Analysis of Variance)이다. 이에 대한 설명으로 적절하지 않은 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><table class=\"q-tbl\"><tr><th>요인</th><th>제곱합</th><th>자유도</th><th>제곱평균</th><th>F</th></tr><tr><td>회귀</td><td>SSR</td><td>1</td><td>MSR=SSR/1</td><td>F=8×SSR/SSE</td></tr><tr><td>잔차</td><td>SSE</td><td>8</td><td>MSE=SSE/8</td><td></td></tr><tr><td>합계</td><td>SST</td><td>9</td><td></td><td></td></tr></table></div>","choices":[{"n":1,"html":"관측값의 개수는 n=10이다."},{"n":2,"html":"종속변수의 표본분산은 SST/(n-1)로 구한다."},{"n":3,"html":"결정계수는 R²=SSR/SST로 계산된다."},{"n":4,"html":"검정통계량 F=8×SSR/SSE로부터 구한 유의확률을 이용해 독립변수에 대한 등분산성을 검정한다."}],"answer":[4],"explain":{"mine":"<p>회귀분석의 F-검정은 <b>회귀모형(기울기)의 유의성</b>을 검정하는 것이지 등분산성을 검정하는 것이 아닙니다(4번이 옳지 않음). 합계 자유도 9 = n−1에서 n=10, 표본분산 = SST/(n−1), R² = SSR/SST은 모두 맞습니다.</p>"}},{"id":"6a6a00631bbde79cd2c72bef","number":50,"category":"빅데이터 모델링","type":"choice","subject":"<p>딥러닝의 오토인코더(Autoencoder)에 관한 설명 중 가장 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"입력을 내부 표현으로 변환하는 인코더는 인지 네트워크라고도 불린다."},{"n":2,"html":"오토인코더는 비지도 학습을 대표하는 모델 중 하나이다."},{"n":3,"html":"오토인코더는 학습 단계에서만 활용되고, 테스트 단계에서는 통상적으로 사용하지 않는다."},{"n":4,"html":"내부 표현을 출력으로 변환하는 디코더는 생성 네트워크라고도 불린다."}],"answer":[3],"explain":{"mine":"<p>오토인코더는 학습 후에도 인코더로 차원 축소·특징 추출을 하고, 복원 오차로 이상치를 탐지하는 등 <b>테스트(추론) 단계에서도 활용</b>됩니다. '학습 단계에서만 활용된다'는 3번이 옳지 않습니다. 인코더=인지 네트워크, 디코더=생성 네트워크라는 명칭, 비지도 학습이라는 설명은 맞습니다.</p>"}},{"id":"6a6a00631bbde79cd2c72bf6","number":51,"category":"빅데이터 모델링","type":"choice","subject":"<p>네트워크 분석에서 노드 간 연결이 어느 정도로 이루어져 있는지 파악하고자 할 때 활용하는 척도는?</p>","choices":[{"n":1,"html":"연결 전이성(Transitivity)"},{"n":2,"html":"연결 강도(Strength)"},{"n":3,"html":"밀도(Density)"},{"n":4,"html":"디그리(Degree)"}],"answer":[3],"explain":{"mine":"<p>네트워크 전체에서 <b>가능한 연결 대비 실제 연결의 비율</b>로 연결 정도를 재는 척도는 <b>밀도(Density)</b>입니다. 디그리는 개별 노드 하나에 연결된 엣지 수를 세는 지표라는 점에서 다릅니다.</p>"}},{"id":"6a6a00631bbde79cd2c72bf5","number":52,"category":"빅데이터 모델링","type":"choice","subject":"<p>워드 임베딩 기법에서 단어들 간의 유사성을 측정하는 방식에 관한 설명 중 가장 적절한 것은?</p>","choices":[{"n":1,"html":"자연어 처리 분야에서 워드 임베딩은 텍스트 데이터를 컴퓨터가 처리할 수 있도록 문자열 벡터 형태로 바꾸는 기술이다."},{"n":2,"html":"코사인 유사도는 최댓값이 1이며, 유사도 값이 클수록 두 단어가 서로 유사하다고 판단한다."},{"n":3,"html":"자카드 유사도의 값이 클수록 두 집합이 공유하지 않는 요소가 많으므로 서로 유사하지 않다고 판단한다."},{"n":4,"html":"단어들 간 유사성을 측정할 때 워드 임베딩에서는 코사인 유사도보다 절대 거리를 재는 기법이 주로 활용된다."}],"answer":[2],"explain":{"mine":"<p><b>코사인 유사도는 두 벡터 사이 각도의 코사인 값으로 최대 1이며, 클수록 유사</b>합니다(2번). 워드 임베딩은 문자열이 아닌 실수 벡터로 바꾸는 기술이고(1번 오답), 자카드 유사도는 클수록 공유 요소가 많다는 뜻이며(3번 오답), 임베딩 유사도 측정에는 절대 거리보다 코사인 유사도가 주로 쓰입니다(4번 오답).</p>"}},{"id":"6a6a00631bbde79cd2c72bed","number":53,"category":"빅데이터 모델링","type":"choice","subject":"<p>역전파 알고리즘에 관한 다음 설명 중 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"시그모이드, 렐루, Tanh 같은 활성화 함수에 각 뉴런의 출력을 통과시켜 비선형성을 부여한다."},{"n":2,"html":"배치 크기, 학습률, 에포크 수와 같은 하이퍼 파라미터를 조정해 모델 성능을 최적화한다."},{"n":3,"html":"생성적 적대 신경망과 컨벌루션 신경망에는 적용할 수 없다."},{"n":4,"html":"데이터를 학습하는 과정에서 신경망의 가중치와 바이어스를 최적화한다."}],"answer":[3],"explain":{"mine":"<p>역전파는 미분 가능한 신경망이라면 <b>GAN이든 CNN이든 모두 적용되는</b> 학습 알고리즘입니다. '적용할 수 없다'는 3번이 옳지 않습니다. 활성화 함수로 비선형성 부여, 하이퍼파라미터 조정, 가중치·바이어스 최적화는 맞는 설명입니다.</p>"}},{"id":"6a6a00631bbde79cd2c72beb","number":54,"category":"빅데이터 모델링","type":"choice","subject":"<p>시계열분석에서는 과거의 자료를 바탕으로 미래 값을 예측하는 여러 기법이 활용된다. 다음 중 이러한 시계열분석 기법의 수식으로 옳지 않은 것은? (단, 시점 t에서 S_t는 예측값, Y_t는 관측값, T_t는 추세변동의 평균값, n은 관측 자료의 개수, (α, β, ω_i)은 0과 1의 상수이다)</p>","choices":[{"n":1,"html":"평균기법 : <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S</mi><mi>t</mi></msub><mo>=</mo><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mfrac><mrow><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><msub><mi>Y</mi><mi>i</mi></msub></mrow><mi>n</mi></mfrac></mstyle></mrow></semantics></math></span>"},{"n":2,"html":"가중평균법 : <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S</mi><mi>t</mi></msub><mo>=</mo><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mfrac><mrow><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><msub><mi>ω</mi><mi>i</mi></msub><mtext> </mtext><msub><mi>Y</mi><mrow><mi>t</mi><mo>−</mo><mi>i</mi></mrow></msub></mrow><mrow><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><msub><mi>ω</mi><mi>i</mi></msub></mrow></mfrac></mstyle></mrow></semantics></math></span>"},{"n":3,"html":"단순기법 : <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S</mi><mi>t</mi></msub><mo>=</mo><msub><mi>Y</mi><mi>t</mi></msub></mrow></semantics></math></span>"},{"n":4,"html":"단순지수 평활법 : <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S</mi><mi>t</mi></msub><mo>=</mo><mi>α</mi><msub><mi>Y</mi><mi>t</mi></msub><mo>+</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>−</mo><mi>α</mi><mo stretchy=\"false\">)</mo><msub><mi>S</mi><mrow><mi>t</mi><mo>−</mo><mn>1</mn></mrow></msub><mo>+</mo><mi>β</mi><msub><mi>T</mi><mi>t</mi></msub></mrow></semantics></math></span>"}],"answer":[4],"explain":{"mine":"<p>단순지수평활법의 식은 S_t = αY_t + (1−α)S_{t−1}까지입니다. 여기에 <b>추세항 βT_t가 추가된 것은 홀트(Holt)의 이중지수평활법</b>이므로 이를 단순지수평활법이라 한 4번이 옳지 않습니다. 평균기법·가중평균법·단순기법(직전 관측값 사용)의 식은 맞습니다.</p>"}},{"id":"6a6a00631bbde79cd2c72bf7","number":55,"category":"빅데이터 모델링","type":"choice","subject":"<p>앙상블 분석에 관한 다음 설명 가운데 옳지 않은 것은 무엇인가?</p>","choices":[{"n":1,"html":"랜덤포레스트는 약한 모형을 순차적으로 결합해 강한 모형을 만드는 부스팅 기법의 일종이다."},{"n":2,"html":"배깅은 다수의 약한 모델을 학습시킨 뒤 이들의 예측을 결합해 최종 예측을 도출한다."},{"n":3,"html":"배깅에서는 원본 데이터셋으로부터 중복을 허용해 부트스트랩 샘플을 여러 개 만든다."},{"n":4,"html":"부스팅은 모델을 순차적으로 학습시키면서 이전 모델의 오류를 보완해 나간다."}],"answer":[1],"explain":{"mine":"<p>랜덤포레스트는 부트스트랩 표본으로 트리를 <b>병렬 독립 학습시키는 배깅 기반</b>(+ 변수 임의 선택) 앙상블입니다. '부스팅 기법의 일종'이라는 1번이 옳지 않습니다. 배깅의 결합 예측, 부트스트랩 중복 추출, 부스팅의 순차 보완 설명은 맞습니다.</p>"}},{"id":"6a6a00621bbde79cd2c72be7","number":56,"category":"빅데이터 모델링","type":"choice","subject":"<p>종속변수가 이산형일 때 의사결정나무 분석에서 트리 분리 기준으로 활용하기에 가장 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"지니 지수"},{"n":2,"html":"F-통계량"},{"n":3,"html":"엔트로피 지수"},{"n":4,"html":"카이제곱 통계량"}],"answer":[2],"explain":{"mine":"<p>이산형(범주형) 목표변수의 분리 기준은 지니 지수, 엔트로피, 카이제곱 통계량입니다. <b>F-통계량(분산분석)은 연속형 목표변수</b>의 회귀나무에서 쓰는 기준이므로 2번이 답입니다.</p>"}},{"id":"6a6a00631bbde79cd2c72bf1","number":57,"category":"빅데이터 모델링","type":"choice","subject":"<p>딥러닝에서 쓰이는 활성화 함수에 관한 설명 중 가장 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"ReLU 함수를 사용하면 기울기 소멸(Gradient Vanishing) 문제를 어느 정도 완화할 수 있다."},{"n":2,"html":"딥러닝에서는 일반적으로 비선형 함수를 활성화 함수로 사용한다."},{"n":3,"html":"입력이 0 이하일 때 기울기가 0이 되어 학습이 이루어지지 않는 문제를 해결하고자 Exponential Linear Unit 함수를 사용한다."},{"n":4,"html":"시그모이드 함수를 미분하면 x=0에서 최솟값을 가진다."}],"answer":[4],"explain":{"mine":"<p>시그모이드의 도함수 σ(x)(1−σ(x))는 <b>x=0에서 최댓값(0.25)</b>을 가집니다. '최솟값'이라고 한 4번이 옳지 않습니다. ReLU의 기울기 소실 완화(1번), 비선형 활성화 함수 사용(2번), dying ReLU를 보완하는 ELU(3번)는 맞는 설명입니다.</p>"}},{"id":"6a6a00631bbde79cd2c72be8","number":58,"category":"빅데이터 모델링","type":"choice","subject":"<p>아래 설명의 (가), (나)에 해당하는 용어로 가장 적절한 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p>서포트벡터머신(SVM, Support Vector Machine)에서 초평면과 직교하는 것은 (가)이고, offset을 결정하는 것은 (나)이다.</p></div>","choices":[{"n":1,"html":"(가) : 마진, (나) : 편향"},{"n":2,"html":"(가) : 마진, (나) : 커널"},{"n":3,"html":"(가) : 가중치 벡터, (나) : 커널"},{"n":4,"html":"(가) : 가중치 벡터, (나) : 편향"}],"answer":[4],"explain":{"mine":"<p>SVM의 초평면은 wᵀx + b = 0으로 표현되며, <b>가중치 벡터 w는 초평면에 직교</b>하는 법선 방향이고 <b>편향 b가 초평면의 위치(offset)를 결정</b>합니다(4번). 마진은 초평면과 서포트벡터 사이의 거리이고, 커널은 비선형 매핑 도구입니다.</p>"}},{"id":"6a6a00621bbde79cd2c72be5","number":59,"category":"빅데이터 모델링","type":"choice","subject":"<p>독립변수들 간에 상관관계가 존재하는지, 다시 말해 다중공선성을 진단하기 위한 지표로 가장 적절한 것은?</p>","choices":[{"n":1,"html":"Adjusted R-squared"},{"n":2,"html":"쿡의 거리(Cook&#x27;s Distance)"},{"n":3,"html":"분산팽창지수(Variance Inflation Factor)"},{"n":4,"html":"Akaike Information Criterion"}],"answer":[3],"explain":{"mine":"<p>다중공선성 진단 지표는 <b>분산팽창지수(VIF)</b>로, 통상 10 이상이면 다중공선성이 있다고 판단합니다. Adjusted R²는 모형 설명력, 쿡의 거리는 영향점(influential point) 진단, AIC는 모형 선택 지표입니다.</p>"}},{"id":"6a6a00631bbde79cd2c72bf3","number":60,"category":"빅데이터 모델링","type":"choice","subject":"<p>심층 신경망을 학습시킬 때 비용함수를 최소화하도록 가중치를 갱신하는 경사하강법 계열의 최적화 알고리즘에 해당하지 않는 것으로 가장 적절한 것은?</p>","choices":[{"n":1,"html":"Nesterov Accelerated Gradient"},{"n":2,"html":"RMSProp"},{"n":3,"html":"Adaboost"},{"n":4,"html":"Adagrad"}],"answer":[3],"explain":{"mine":"<p>NAG, RMSProp, Adagrad는 모두 경사하강법을 개선한 최적화 알고리즘입니다. <b>Adaboost는 약한 분류기를 순차 결합하는 부스팅 앙상블 기법</b>이지 경사하강 계열 최적화 알고리즘이 아니므로 3번이 답입니다.</p>"}},{"id":"6a6a00631bbde79cd2c72bfc","number":61,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>두 변수 간의 상관관계를 나타내는 방법에 대한 설명으로 가장 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"히트맵은 데이터의 밀도나 빈도를 색상으로 표현하여, 값의 분포와 변동을 시각적으로 보여준다."},{"n":2,"html":"두 변수 사이의 산점도는 항상 히트맵으로 시각화하여 표현된다."},{"n":3,"html":"산점도에서는 각 점이 데이터의 한 관측값에 해당하며, 두 변수의 값은 x축과 y축으로 표현된다."},{"n":4,"html":"상관관계 네트워크 형태를 활용할 경우 변수는 노드로, 상관관계는 엣지로 나타낸다."}],"answer":[2],"explain":{"mine":"<p>산점도는 그 자체로 완결된 시각화이며, 데이터가 매우 많을 때 밀도 기반 히트맵으로 보완할 수 있을 뿐 '<b>항상 히트맵으로 시각화된다</b>'는 2번은 옳지 않습니다. 히트맵의 색상 표현, 산점도의 관측값-좌표 대응, 상관관계 네트워크의 노드·엣지 표현은 맞습니다.</p>"}},{"id":"6a6a00631bbde79cd2c72bfd","number":62,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>확보한 데이터의 개수가 적은 경우에 주로 활용되는 교차검증 방법으로 옳은 것은?</p>","choices":[{"n":1,"html":"K-fold 교차검증(K-fold Cross Validation)"},{"n":2,"html":"LOOCV(Leave-one-out Cross Validation)"},{"n":3,"html":"홀드아웃 교차검증(Hold-Out Cross Validation)"},{"n":4,"html":"계층별 K-fold 교차검증(Stratified K-fold Cross Validation)"}],"answer":[2],"explain":{"mine":"<p>데이터가 적을 때는 <b>LOOCV</b>가 적합합니다. 매번 1개만 검증에 쓰고 나머지 전부(n−1개)를 학습에 활용하므로 적은 데이터를 최대한 아껴 쓸 수 있기 때문입니다. 계산량은 많지만 데이터가 적으면 부담이 크지 않습니다.</p>"}},{"id":"6a6a00631bbde79cd2c72c02","number":63,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>아래 보기에서 설명하고 있는 군집분석 기법은 무엇인가?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>사전에 군집의 수를 지정하지 않아도 된다.</li><li>적절한 수준까지는 군집의 수가 많을수록 성능이 좋아지는 특징이 있다.</li><li>군집에 포함되는 최대 거리와 필요한 최소 데이터 포인트 수를 활용한다.</li><li>데이터의 밀도 중심을 탐색하는 방식으로 군집을 만들어 낸다.</li></ul></div>","choices":[{"n":1,"html":"K-medoids Clustering"},{"n":2,"html":"DBSCAN"},{"n":3,"html":"Agglomerative Clustering"},{"n":4,"html":"Self-organizing Map"}],"answer":[2],"explain":{"mine":"<p>군집 수를 미리 정하지 않고, 반경 내 최소 데이터 개수라는 <b>밀도 조건으로 군집을 확장</b>해 나가는 기법은 <b>DBSCAN</b>입니다. '최대 거리(ε)와 최소 데이터 포인트 수(minPts)'라는 두 파라미터가 결정적 힌트입니다.</p>"}},{"id":"6a6a00631bbde79cd2c72c05","number":64,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>인공신경망에 관한 다음 설명 중 옳은 것은 무엇인가?</p>","choices":[{"n":1,"html":"인공신경망에서는 일반적으로 선형적 구조의 활성화 함수가 주로 사용된다."},{"n":2,"html":"인공신경망의 성능은 은닉층의 개수와 관련이 없다."},{"n":3,"html":"소프트맥스 활성화 함수를 사용하고 은닉층이 1개인 경우, 해당 모델의 성능은 로지스틱 회귀분석 모형과 동일하다."},{"n":4,"html":"시그모이드 활성화 함수를 사용하면서 은닉층이 없는 경우, 수학적으로 로지스틱 회귀분석 모형과 동일하다."}],"answer":[4],"explain":{"mine":"<p>은닉층 없이 입력을 시그모이드에 바로 통과시키는 신경망은 수학적으로 <b>로지스틱 회귀와 동일</b>합니다(4번). 신경망은 비선형 활성화 함수를 쓰는 것이 일반적이고(1번 오답), 은닉층 수는 성능과 직결되며(2번 오답), 은닉층이 있으면 로지스틱 회귀보다 표현력이 커집니다(3번 오답).</p>"}},{"id":"6a6a00631bbde79cd2c72bf9","number":65,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>ROC(Receiver Operating Characteristic) 곡선에서 x축(가로축)은 오분류율(거짓 긍정률, FP rate)로 표시된다. 이때 y축(세로축)에 해당하는 것은 무엇인가?</p>","choices":[{"n":1,"html":"정밀도"},{"n":2,"html":"특이도"},{"n":3,"html":"민감도"},{"n":4,"html":"정확도"}],"answer":[3],"explain":{"mine":"<p>ROC 곡선의 y축은 <b>민감도(TPR, 참 긍정률)</b>입니다. x축의 거짓 긍정률(FPR)은 1−특이도와 같으므로, ROC 곡선은 '민감도 vs 1−특이도'의 궤적이라고도 표현합니다.</p>"}},{"id":"6a6a00631bbde79cd2c72c07","number":66,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>빅데이터 분석결과를 명확하고 객관적으로 평가할 수 있는 다음과 같은 평가 방법을 무엇이라 하는가?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>미리 정해진 명확한 Standard를 기준으로 분석결과의 성과를 평가한다.</li><li>데이터 분석이 당초 의도한 목표에 부합하게 수행되었는지 평가한다.</li><li>기존의 평가 방법과 결과에 대한 벤치마킹 결과를 활용한다.</li><li>모델의 성능이 요구되는 수준을 충족하는지를 확인하는 데 효과적이다.</li></ul></div>","choices":[{"n":1,"html":"성과지표 평가(KPI Assessment)"},{"n":2,"html":"ROC 평가(ROC Assessment)"},{"n":3,"html":"기준기반 평가(Criterion-referenced Assessment)"},{"n":4,"html":"교차 평가(Cross Assessment)"}],"answer":[3],"explain":{"mine":"<p>사전에 정해진 명확한 기준(Standard)에 비추어 목표 부합 여부와 요구 수준 충족 여부를 평가하는 방법은 <b>기준기반 평가(Criterion-referenced Assessment)</b>입니다. 벤치마킹 결과를 기준으로 활용한다는 것도 특징입니다.</p>"}},{"id":"6a6a00631bbde79cd2c72bfb","number":67,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>다음 중 동질성 검정(Homogeneity Test)에 관한 설명으로 옳지 않은 것은?</p>","choices":[{"n":1,"html":"두 개 이상의 모집단이 서로 동일한 분포를 따르는지를 확인하기 위한 통계적 방법이 동질성 검정이다."},{"n":2,"html":"동질성 검정에서 표본 추출은 일반적으로 군집추출방법으로 이루어진다."},{"n":3,"html":"동질성 검정에 사용되는 각 표본은 서로 독립적으로 추출되어야 한다."},{"n":4,"html":"동질성 검정에서 검정통계량으로는 일반적으로 카이제곱 검정통계량이 사용된다."}],"answer":[2],"explain":{"mine":"<p>동질성 검정은 각 모집단(행)에서 <b>독립적인 무작위 표본</b>을 뽑아 분포가 같은지를 카이제곱 통계량으로 확인합니다. 표본추출이 '군집추출로 이루어진다'는 2번이 옳지 않습니다.</p>"}},{"id":"6a6a00631bbde79cd2c72bfa","number":68,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>n개의 데이터에서 실제값(A_i)과 예측값(F_i) 사이의 차이를 비교하려고 한다. 평균절대백분율오차를 계산하는 식으로 옳은 것은 다음 중 무엇인가?</p>","choices":[{"n":1,"html":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msqrt><mrow><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mfrac><mn>1</mn><mi>n</mi></mfrac></mstyle><msubsup><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></msubsup><mo stretchy=\"false\">(</mo><msub><mi>A</mi><mi>i</mi></msub><mo>−</mo><msub><mi>F</mi><mi>i</mi></msub><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup></mrow></msqrt></mrow></semantics></math></span>"},{"n":2,"html":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mfrac><mn>1</mn><mi>n</mi></mfrac></mstyle><msubsup><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></msubsup><mo stretchy=\"false\">∣</mo><msub><mi>A</mi><mi>i</mi></msub><mo>−</mo><msub><mi>F</mi><mi>i</mi></msub><mo stretchy=\"false\">∣</mo></mrow></semantics></math></span>"},{"n":3,"html":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mfrac><mn>1</mn><mi>n</mi></mfrac></mstyle><msubsup><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></msubsup><mrow><mo fence=\"true\">∣</mo><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mfrac><mrow><msub><mi>A</mi><mi>i</mi></msub><mo>−</mo><msub><mi>F</mi><mi>i</mi></msub></mrow><msub><mi>A</mi><mi>i</mi></msub></mfrac></mstyle><mo fence=\"true\">∣</mo></mrow><mo>×</mo><mn>100</mn></mrow></semantics></math></span>"},{"n":4,"html":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mfrac><mn>1</mn><mi>n</mi></mfrac></mstyle><msubsup><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></msubsup><mo stretchy=\"false\">(</mo><msub><mi>A</mi><mi>i</mi></msub><mo>−</mo><msub><mi>F</mi><mi>i</mi></msub><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup></mrow></semantics></math></span>"}],"answer":[3],"explain":{"mine":"<p>평균절대백분율오차(MAPE)는 오차를 실제값으로 나눈 <b>백분율의 절댓값 평균</b>인 3번 식입니다. 1번은 RMSE, 2번은 MAE, 4번은 MSE의 식입니다. MAPE는 단위가 %라서 서로 다른 스케일의 예측 문제를 비교할 때 유용합니다.</p>"}},{"id":"6a6a00631bbde79cd2c72c09","number":69,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>시각화 결과물은 작성자의 의도나 실수 때문에 데이터 왜곡이 일어날 수 있다. 다음 중 데이터 왜곡에 해당하지 않는 것은?</p>","choices":[{"n":1,"html":"지역별 과일 수확량을 비교하면서 감과 배만 나타내고 나머지 과일의 수확량은 제외한 그래프"},{"n":2,"html":"(열대, 남극, 북극) 지역의 계절에 따른 온도 변화를 표현한 극좌표"},{"n":3,"html":"파이차트를 3차원으로 회전시켜 나타낸 것"},{"n":4,"html":"성적 간 큰 차이가 없음에도 세로축(y축)의 시작점을 조정하여 그린 막대 그래프"}],"answer":[3],"explain":{"mine":"<p>극좌표로 계절별 온도 변화를 표현하는 것은 주기성 데이터에 적합한 <b>정당한 시각화 방식</b>입니다(2번이 답). 일부 항목만 골라 보여주기(1번), 3차원 회전 파이차트(3번 — 원근 때문에 비율 왜곡), y축 시작점 조작(4번)은 모두 대표적인 데이터 왜곡 사례입니다.</p>"}},{"id":"6a6a00631bbde79cd2c72c0b","number":70,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>다차원 데이터(Multidimensional Data)를 시각화하는 방법에 관한 설명 중 가장 적절한 것은 무엇인가?</p>","choices":[{"n":1,"html":"변수 간 선형적 상관관계의 계수 값을 그래프 형태로 표현한다."},{"n":2,"html":"그룹 간 분산을 비교하고자 박스플롯을 활용해 시각화한 결과를 보여준다."},{"n":3,"html":"로지스틱 회귀분석의 결과를 바탕으로 여러 클래스의 분류 결과를 ROC 곡선으로 나타낸다."},{"n":4,"html":"주성분 분석을 활용해 데이터의 분산이 최대가 되는 새로운 축을 찾아 그 축에 데이터를 투영한다."}],"answer":[4],"explain":{"mine":"<p>다차원 데이터 시각화의 핵심은 차원 축소입니다. <b>주성분 분석으로 분산이 최대인 새 축을 찾아 데이터를 투영</b>하면 고차원 데이터를 2~3차원 그림으로 표현할 수 있습니다(4번). 나머지는 특정 2변수 관계나 모델 평가에 대한 설명이라 다차원 시각화 방법으로 부적합합니다.</p>"}},{"id":"6a6a00631bbde79cd2c72bf8","number":71,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>혼동행렬을 활용하여 성능평가 지표를 계산하는 방법에 대한 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"거짓 긍정률은 실제 부정인 범주 가운데 긍정으로 잘못 예측된 비율을 말한다."},{"n":2,"html":"민감도는 실제 긍정인 범주 가운데 긍정으로 올바르게 예측된 비율을 말한다."},{"n":3,"html":"특이도는 실제 부정인 범주 가운데 부정으로 올바르게 예측된 비율을 말한다."},{"n":4,"html":"정확도는 긍정으로 예측된 것 가운데 실제로 긍정인 비율을 말한다."}],"answer":[4],"explain":{"mine":"<p>'긍정으로 예측한 것 가운데 실제 긍정인 비율'은 정확도가 아니라 <b>정밀도(Precision)</b>입니다(4번이 옳지 않음). 정확도는 전체 중 맞게 예측한 비율 (TP+TN)/전체입니다. 거짓 긍정률·민감도·특이도의 정의는 모두 맞습니다.</p>"}},{"id":"6a6a00631bbde79cd2c72c0a","number":72,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>아래 박스플롯을 해석한 내용 중 옳지 않은 것을 고르시오.</p><div class=\"q-fig\"><svg class=\"q-fig__svg\" viewBox=\"0 0 520 420\" width=\"520\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"Group A와 Group B의 데이터 분포를 비교하는 박스플롯 그림\"><line x1=\"80\" y1=\"350\" x2=\"480\" y2=\"350\" stroke=\"currentColor\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/><line x1=\"80\" y1=\"275\" x2=\"480\" y2=\"275\" stroke=\"currentColor\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/><line x1=\"80\" y1=\"200\" x2=\"480\" y2=\"200\" stroke=\"currentColor\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/><line x1=\"80\" y1=\"125\" x2=\"480\" y2=\"125\" stroke=\"currentColor\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/><line x1=\"80\" y1=\"50\" x2=\"480\" y2=\"50\" stroke=\"currentColor\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/><line x1=\"80\" y1=\"30\" x2=\"80\" y2=\"360\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"80\" y1=\"360\" x2=\"480\" y2=\"360\" stroke=\"currentColor\" stroke-width=\"2\"/><text x=\"70\" y=\"355\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"end\">10</text><text x=\"70\" y=\"280\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"end\">20</text><text x=\"70\" y=\"205\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"end\">30</text><text x=\"70\" y=\"130\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"end\">40</text><text x=\"70\" y=\"55\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"end\">50</text><line x1=\"200\" y1=\"335\" x2=\"200\" y2=\"282.5\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"170\" y1=\"335\" x2=\"230\" y2=\"335\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"200\" y1=\"140\" x2=\"200\" y2=\"87.5\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"170\" y1=\"87.5\" x2=\"230\" y2=\"87.5\" stroke=\"currentColor\" stroke-width=\"2\"/><rect x=\"150\" y=\"140\" width=\"100\" height=\"142.5\" fill=\"rgb(220,220,220)\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"150\" y1=\"200\" x2=\"250\" y2=\"200\" stroke=\"currentColor\" stroke-width=\"3\"/><line x1=\"380\" y1=\"350\" x2=\"380\" y2=\"312.5\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"350\" y1=\"350\" x2=\"410\" y2=\"350\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"380\" y1=\"215\" x2=\"380\" y2=\"140\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"350\" y1=\"140\" x2=\"410\" y2=\"140\" stroke=\"currentColor\" stroke-width=\"2\"/><rect x=\"330\" y=\"215\" width=\"100\" height=\"97.5\" fill=\"rgb(80,80,80)\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"330\" y1=\"260\" x2=\"430\" y2=\"260\" stroke=\"rgb(255,255,255)\" stroke-width=\"3\"/><circle cx=\"380\" cy=\"102.5\" r=\"4\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"380\" cy=\"80\" r=\"4\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"380\" cy=\"57.5\" r=\"4\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><text x=\"200\" y=\"390\" font-size=\"18\" fill=\"currentColor\" text-anchor=\"middle\">Group A</text><text x=\"380\" y=\"390\" font-size=\"18\" fill=\"currentColor\" text-anchor=\"middle\">Group B</text></svg></div>","choices":[{"n":1,"html":"Group B의 평균은 20에 근접한다."},{"n":2,"html":"Group B에서는 이상치가 관찰된다."},{"n":3,"html":"Group A의 중앙값이 Group B의 중앙값보다 크다."},{"n":4,"html":"Group A의 1사분위수는 20에 근접한다."}],"answer":[1],"explain":{"mine":"<p>박스플롯은 평균을 표시하지 않으며, Group B는 위쪽에 이상치(약 42~49)가 있어 평균이 중앙값(약 22)보다 높게 끌려 올라갈 가능성이 큽니다. 따라서 '평균이 20에 근접한다'고 단정한 1번이 옳지 않습니다. B의 이상치 존재, A 중앙값(약 30) &gt; B 중앙값(약 22), A의 Q1 ≈ 20은 그림과 일치합니다.</p>"}},{"id":"6a6a00631bbde79cd2c72c04","number":73,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>다음 거래 데이터가 주어졌을 때, 연관규칙 &#x27;{오렌지, 사과} ⇒ {자몽}&#x27;의 지지도와 신뢰도를 순서대로 구하면?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>{오렌지, 사과}</li><li>{수박, 레몬, 딸기}</li><li>{오렌지, 사과, 수박}</li><li>{오렌지, 사과, 자몽}</li><li>{오렌지, 사과, 자몽, 레몬}</li><li>{오렌지, 사과, 자몽, 딸기}</li></ul></div>","choices":[{"n":1,"html":"지지도=33%, 신뢰도=60%"},{"n":2,"html":"지지도=33%, 신뢰도=67%"},{"n":3,"html":"지지도=50%, 신뢰도=60%"},{"n":4,"html":"지지도=50%, 신뢰도=67%"}],"answer":[3],"explain":{"mine":"<p>지지도 = {오렌지, 사과, 자몽}이 모두 포함된 거래 3건 ÷ 전체 6건 = <b>50%</b>. 신뢰도 = 3건 ÷ {오렌지, 사과} 포함 거래 5건 = <b>60%</b>입니다(3번).</p>"}},{"id":"6a6a00631bbde79cd2c72bff","number":74,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>이산형 변수들에 대한 동질성, 독립성, 적합도 검정을 설명한 내용 중 가장 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"귀무가설이 참이라는 가정하에 기대되는 기대빈도를 활용한다."},{"n":2,"html":"일반적으로 F-검정통계량이 검정통계량으로 사용된다."},{"n":3,"html":"실제 데이터에서 관측된 관찰빈도를 활용한다."},{"n":4,"html":"검정통계량 분포를 이용하며, 각 검정의 자유도는 검정 유형 및 범주의 수에 따라 달라진다."}],"answer":[2],"explain":{"mine":"<p>동질성·독립성·적합도 검정은 모두 관찰빈도와 기대빈도의 차이를 이용하는 <b>카이제곱 검정</b>입니다. 'F-검정통계량이 사용된다'는 2번이 옳지 않습니다. 자유도가 검정 유형·범주 수에 따라 달라진다는 것도 맞습니다.</p>"}},{"id":"6a6a00631bbde79cd2c72c08","number":75,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>시공간 시각화와 관련된 설명 중 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"데이터를 시각적으로 표현할 때 시간 차원과 공간 차원을 함께 고려한다."},{"n":2,"html":"시공간 시각화의 대표적인 예로 등고선 지도(Contour Map)를 들 수 있다."},{"n":3,"html":"기상학, 교통분석, 환경 모니터링, 도시 계획, 질병 확산 등 여러 분야에서 활용되고 있다."},{"n":4,"html":"GIS, Tableau, D3.js 등 다양한 도구를 활용해 시각화가 가능하다."}],"answer":[2],"explain":{"mine":"<p>등고선 지도는 고도나 기압처럼 <b>공간상의 연속 값</b>을 나타내는 공간 시각화이지, 시간 차원을 함께 담는 시공간 시각화의 대표 예가 아닙니다(2번이 옳지 않음). 시공간 시각화는 시간 흐름에 따른 공간 데이터의 변화(질병 확산 애니메이션 등)를 표현합니다.</p>"}},{"id":"6a6a00631bbde79cd2c72c00","number":76,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>과적합을 방지하기 위한 기법 중, 학습 과정에서 신경망의 일부 노드를 사용하지 않는 방법은 무엇인가?</p>","choices":[{"n":1,"html":"드롭아웃"},{"n":2,"html":"데이터 증강"},{"n":3,"html":"교차검증"},{"n":4,"html":"피처 추가"}],"answer":[1],"explain":{"mine":"<p>학습 과정에서 <b>일부 노드를 무작위로 꺼서(비활성화)</b> 특정 노드에 대한 의존을 막는 과적합 방지 기법은 <b>드롭아웃</b>입니다. 매 배치마다 다른 노드 조합이 학습되어 앙상블과 유사한 효과를 냅니다.</p>"}},{"id":"6a6a00631bbde79cd2c72c01","number":77,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>다음 중 군집분석에 관한 설명으로 옳지 않은 것은?</p>","choices":[{"n":1,"html":"군집의 품질 평가에는 군집 내 응집도와 군집 간 분리도를 바탕으로 계산되는 실루엣 지수가 활용된다."},{"n":2,"html":"K-means는 K개의 군집 중심을 사전에 설정한 뒤, 각 데이터 포인트를 가장 가까운 군집 중심에 배정하는 비계층적 군집분석 기법 중 하나이다."},{"n":3,"html":"계층적 군집분석에서는 분석 과정 중 개체가 소속 군집을 자유롭게 옮겨 다니면서 최적의 군집이 결정된다."},{"n":4,"html":"군집 수를 정할 때는 군집 수에 따른 총제곱합을 표시한 엘보우 그래프를 활용한다."}],"answer":[3],"explain":{"mine":"<p>계층적 군집분석에서는 한 번 병합(또는 분리)된 개체가 <b>다른 군집으로 옮겨갈 수 없습니다</b>. '소속 군집을 자유롭게 옮겨 다닌다'는 3번이 옳지 않습니다 — 소속 재배정이 반복되는 것은 K-means 같은 비계층적 방법의 특징입니다.</p>"}},{"id":"6a6a00631bbde79cd2c72bfe","number":78,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>교차분석(Cross Tabulation Analysis)에 관한 다음 설명 중 가장 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"두 변수가 서로 어떻게 상호작용하는지 파악하는 데 교차분석은 유용하게 활용되는 방법이다."},{"n":2,"html":"카이제곱 동일성 검정에서는 관찰빈도와 기대빈도를 비교하여 여러 집단이 동일한 분포를 따르는지 아니면 집단 간에 차이가 존재하는지를 확인한다."},{"n":3,"html":"카이제곱 독립성 검정에서는 두 범주형 변수의 관찰된 빈도를, 두 변수가 서로 독립이라고 가정할 때 기대되는 빈도와 비교한다."},{"n":4,"html":"교차분석 기법 가운데 하나인 적합도 검정에서는 F-분포를 이용해 검정통계량을 구함으로써 관측빈도와 기대빈도 간의 차이를 평가한다."}],"answer":[4],"explain":{"mine":"<p>적합도 검정은 <b>카이제곱 분포</b>를 이용합니다. 'F-분포를 이용한다'는 4번이 옳지 않습니다. 교차분석의 상호작용 파악, 동일성 검정과 독립성 검정의 관찰-기대빈도 비교 설명은 모두 맞습니다.</p>"}},{"id":"6a6a00631bbde79cd2c72c06","number":79,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>아래 각 문제 상황에 가장 적합한 데이터 분석 모형을 옳게 짝지은 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>(가) 영화 리뷰를 긍정 또는 부정으로 분류하는 문제</li><li>(나) 사람 얼굴을 인식하는 프로그램 개발</li><li>(다) 로봇 팔의 동작 알고리즘 개발</li></ul></div>","choices":[{"n":1,"html":"(가) 합성곱 신경망(CNN) / (나) 강화학습을 통한 작업 수행 / (다) 순환 신경망(RNN)"},{"n":2,"html":"(가) 강화학습을 통한 작업 수행 / (나) 합성곱 신경망(CNN) / (다) 순환 신경망(RNN)"},{"n":3,"html":"(가) 순환 신경망(RNN) / (나) 합성곱 신경망(CNN) / (다) 강화학습을 통한 작업 수행"},{"n":4,"html":"(가) 합성곱 신경망(CNN) / (나) 순환 신경망(RNN) / (다) 강화학습을 통한 작업 수행"}],"answer":[3],"explain":{"mine":"<p>(가) 리뷰 텍스트는 순차 데이터이므로 RNN, (나) 이미지 인식은 CNN, (다) 로봇 팔 동작은 시행착오와 보상으로 학습하는 강화학습이 적합합니다(3번).</p>"}},{"id":"6a6a00631bbde79cd2c72c03","number":80,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>다음 내용이 설명하는 것으로 가장 알맞은 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>K쇼핑몰에서 고객이 과거에 구입한 제품 목록을 살펴보고 제품을 구매하려고 한다.</li><li>구매 항목(Item) 집합 간의 규칙이나 항목 사이의 관계를 찾아낸다.</li><li>구매 항목 A가 있을 때 항목 B도 함께 존재하는지 확인한다.</li><li>자주 구매되는 항목들의 집합을 기반으로 만들어진다.</li></ul></div>","choices":[{"n":1,"html":"상관계수 행렬(Correlation Matrix)"},{"n":2,"html":"공분산 행렬(Covariance Matrix)"},{"n":3,"html":"연관 규칙(Association Rule)"},{"n":4,"html":"아이템 규칙(Item Rule)"}],"answer":[3],"explain":{"mine":"<p>구매 항목 집합 사이에서 'A를 사면 B도 산다'는 규칙을 찾아내는 기법은 <b>연관 규칙(Association Rule)</b> 분석입니다. 빈발 항목 집합을 기반으로 지지도·신뢰도·향상도로 규칙을 평가합니다.</p>"}}]};